export const dataGridExampleSources = {
  "base-plain": "'use client'\n\nimport { useMemo } from 'react'\n\nimport { DataGrid, useDataGrid } from 'shared/DataGrid'\n\nimport { columns, makeUsers } from '../_data'\n\nexport function BasePlainExample() {\n\tconst data = useMemo(() => makeUsers(50), [])\n\n\tconst table = useDataGrid({\n\t\tdata,\n\t\tcolumns,\n\t\tpagination: { pageSize: 10 },\n\t\tpageSizer: { items: [5, 10, 25] },\n\t})\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#64748b', fontSize: '0.875rem' }}>\n\t\t\t\tMinimal table with pagination and a page-size selector. No sorting, no filtering.\n\t\t\t</p>\n\t\t\t<DataGrid table={table} />\n\t\t</div>\n\t)\n}\n",
  "base-inline": "'use client'\n\nimport { useMemo } from 'react'\n\nimport { DataGrid } from 'shared/DataGrid'\n\nimport { columns, makeUsers } from '../_data'\n\nexport function BaseInlineExample() {\n\tconst data = useMemo(() => makeUsers(50), [])\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#64748b', fontSize: '0.875rem' }}>\n\t\t\t\tNo <code>useDataGrid</code> call — the grid takes the same config inline and runs the hook\n\t\t\t\tfor you. Use this for simple, single-component grids.\n\t\t\t</p>\n\t\t\t<DataGrid\n\t\t\t\tdata={data}\n\t\t\t\tcolumns={columns}\n\t\t\t\tsorting\n\t\t\t\tpagination={{ pageSize: 10 }}\n\t\t\t\tpageSizer={{ items: [5, 10, 25] }}\n\t\t\t/>\n\t\t</div>\n\t)\n}\n",
  "base-sorting": "'use client'\n\nimport { useMemo } from 'react'\n\nimport { DataGrid, useDataGrid } from 'shared/DataGrid'\n\nimport { columns, makeUsers } from '../_data'\n\nexport function BaseSortingExample() {\n\tconst data = useMemo(() => makeUsers(50), [])\n\n\tconst table = useDataGrid({\n\t\tdata,\n\t\tcolumns,\n\t\tsorting: true,\n\t\tpagination: { pageSize: 10 },\n\t\tpageSizer: { items: [5, 10, 25] },\n\t})\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#64748b', fontSize: '0.875rem' }}>\n\t\t\t\tClick a column header to sort by that column. Shift-click for multi-column sorting.\n\t\t\t</p>\n\t\t\t<DataGrid table={table} />\n\t\t</div>\n\t)\n}\n",
  "base-filtering": "'use client'\n\nimport { useMemo } from 'react'\n\nimport { DataGrid, useDataGrid } from 'shared/DataGrid'\n\nimport { columns, makeUsers } from '../_data'\n\nexport function BaseFilteringExample() {\n\tconst data = useMemo(() => makeUsers(50), [])\n\n\tconst table = useDataGrid({\n\t\tdata,\n\t\tcolumns,\n\t\tfiltering: true,\n\t\tpagination: { pageSize: 10 },\n\t\tpageSizer: { items: [5, 10, 25] },\n\t})\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#64748b', fontSize: '0.875rem' }}>\n\t\t\t\tType into the column filter inputs to narrow down rows.\n\t\t\t</p>\n\t\t\t<DataGrid table={table} />\n\t\t</div>\n\t)\n}\n",
  "base-selection": "'use client'\n\nimport { useMemo } from 'react'\n\nimport { DataGrid, useDataGrid } from 'shared/DataGrid'\n\nimport { columns, makeUsers } from '../_data'\n\nexport function BaseSelectionExample() {\n\tconst data = useMemo(() => makeUsers(50), [])\n\n\tconst table = useDataGrid({\n\t\tdata,\n\t\tcolumns,\n\t\tselection: true,\n\t\tpagination: { pageSize: 10 },\n\t\tpageSizer: { items: [5, 10, 25] },\n\t})\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#64748b', fontSize: '0.875rem' }}>\n\t\t\t\tClick checkboxes to select rows. The header checkbox toggles the current page.\n\t\t\t</p>\n\t\t\t<DataGrid table={table} />\n\t\t</div>\n\t)\n}\n",
  "base-sticky": "'use client'\n\nimport { useMemo } from 'react'\n\nimport { DataGrid, useDataGrid } from 'shared/DataGrid'\n\nimport { columns, makeUsers } from '../_data'\n\nexport function BaseStickyExample() {\n\tconst data = useMemo(() => makeUsers(50), [])\n\n\tconst table = useDataGrid({\n\t\tdata,\n\t\tcolumns,\n\t\tstickyHeader: true,\n\t\tpagination: { pageSize: 25 },\n\t\tpageSizer: { items: [10, 25, 50] },\n\t})\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#64748b', fontSize: '0.875rem' }}>\n\t\t\t\tThe header stays fixed while the body scrolls. Container height is controlled by{' '}\n\t\t\t\t<code>--dg-table-max-height</code>.\n\t\t\t</p>\n\t\t\t<DataGrid table={table} />\n\t\t</div>\n\t)\n}\n",
  "base-editing": "'use client'\n\nimport { useState } from 'react'\n\nimport { DataGrid, useDataGrid } from 'shared/DataGrid'\n\nimport { columns, makeUsers, type User } from '../_data'\n\nexport function BaseEditingExample() {\n\tconst [data, setData] = useState<User[]>(() => makeUsers(50))\n\n\tconst table = useDataGrid({\n\t\tdata,\n\t\tcolumns,\n\t\tpagination: { pageSize: 10 },\n\t\tpageSizer: { items: [5, 10, 25] },\n\t\tediting: {\n\t\t\tmode: 'row',\n\t\t\tonSave: ({ rowId, values }) => {\n\t\t\t\tsetData((prev) =>\n\t\t\t\t\tprev.map((row) => (row.id.toString() === rowId ? { ...row, ...values } : row)),\n\t\t\t\t)\n\t\t\t},\n\t\t},\n\t})\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#64748b', fontSize: '0.875rem' }}>\n\t\t\t\tClick the row menu (⋮) to edit a row inline. Changes are saved back into local state.\n\t\t\t</p>\n\t\t\t<DataGrid table={table} />\n\t\t</div>\n\t)\n}\n",
  "base-column-visibility": "'use client'\n\nimport { useMemo } from 'react'\n\nimport { DataGrid, useDataGrid } from 'shared/DataGrid'\n\nimport { columns, makeUsers } from '../_data'\n\nexport function BaseColumnVisibilityExample() {\n\tconst data = useMemo(() => makeUsers(50), [])\n\n\tconst table = useDataGrid({\n\t\tdata,\n\t\tcolumns,\n\t\tcolumnVisibility: { toolbar: true },\n\t\tpagination: { pageSize: 10 },\n\t\tpageSizer: { items: [5, 10, 25] },\n\t})\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#64748b', fontSize: '0.875rem' }}>\n\t\t\t\tUse the <strong>Columns</strong> button in the toolbar to toggle column visibility.\n\t\t\t</p>\n\t\t\t<DataGrid table={table} />\n\t\t</div>\n\t)\n}\n",
  "base-full": "'use client'\n\nimport { useState } from 'react'\n\nimport { DataGrid, useDataGrid } from 'shared/DataGrid'\n\nimport { columns, INITIAL_DATA, type User } from '../_data'\n\nexport function BaseFullExample() {\n\tconst [data, setData] = useState(INITIAL_DATA)\n\n\tconst table = useDataGrid({\n\t\tdata,\n\t\tcolumns,\n\t\tsorting: true,\n\t\tfiltering: true,\n\t\tpagination: { pageSize: 10 },\n\t\tpageSizer: { items: [3, 5, 10] },\n\t\tselection: true,\n\t\tcolumnVisibility: true,\n\t\tselectionBar: {\n\t\t\tonDelete: ({ selectedRows, clearSelection }) => {\n\t\t\t\tsetData((prev) => prev.filter((row) => !selectedRows.some((r) => r.original === row)))\n\t\t\t\tclearSelection()\n\t\t\t},\n\t\t},\n\t\tediting: {\n\t\t\tmode: 'row',\n\t\t\tonSave: ({ rowId, values }) => {\n\t\t\t\tsetData((prev) => prev.map((row) => (row.id.toString() === rowId ? { ...row, ...values } : row)))\n\t\t\t},\n\t\t},\n\t\tcreating: {\n\t\t\tmode: 'pin-row',\n\t\t\tonSave: ({ values }) => {\n\t\t\t\tsetData((prev) => [...prev, values as User])\n\t\t\t},\n\t\t},\n\t\tdeleting: {\n\t\t\tonDelete: ({ row }) => {\n\t\t\t\tsetData((prev) => prev.filter((r) => r.id !== row.original.id))\n\t\t\t},\n\t\t},\n\t})\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#666' }}>\n\t\t\t\tDemonstrates sorting, filtering, pagination, selection, creating (row mode), editing (row mode), and deleting.\n\t\t\t</p>\n\t\t\t<DataGrid table={table} />\n\t\t</div>\n\t)\n}\n",
  "sorting": "'use client'\n\nimport { DataGrid, useDataGrid } from 'shared/DataGrid'\n\ntype Task = {\n\tid: number\n\ttitle: string\n\tpriority: 'low' | 'medium' | 'high' | 'critical'\n\trank: number\n\tdueDate: string\n\tassignee: string | undefined\n}\n\nconst PRIORITY_RANK: Record<Task['priority'], number> = {\n\tcritical: 0,\n\thigh: 1,\n\tmedium: 2,\n\tlow: 3,\n}\n\nconst DATA: Task[] = [\n\t{ id: 1, title: 'Fix auth race condition', priority: 'critical', rank: 1, dueDate: '2026-05-14', assignee: 'Alice' },\n\t{ id: 2, title: 'Migrate analytics pipeline', priority: 'high', rank: 4, dueDate: '2026-05-22', assignee: 'Bob' },\n\t{ id: 3, title: 'Refresh design tokens', priority: 'medium', rank: 7, dueDate: '2026-06-02', assignee: undefined },\n\t{ id: 4, title: 'Backfill historical events', priority: 'high', rank: 3, dueDate: '2026-05-19', assignee: 'Carol' },\n\t{ id: 5, title: 'Tidy onboarding copy', priority: 'low', rank: 12, dueDate: '2026-06-12', assignee: 'David' },\n\t{ id: 6, title: 'Audit permissions matrix', priority: 'critical', rank: 2, dueDate: '2026-05-15', assignee: undefined },\n\t{ id: 7, title: 'Investigate slow query', priority: 'high', rank: 5, dueDate: '2026-05-25', assignee: 'Eve' },\n\t{ id: 8, title: 'Wire up push notifications', priority: 'medium', rank: 9, dueDate: '2026-06-08', assignee: 'Frank' },\n]\n\nexport function SortingExample() {\n\tconst table = useDataGrid({\n\t\tdata: DATA,\n\t\tcolumns: [\n\t\t\t{ accessorKey: 'title', header: 'Title' },\n\t\t\t{\n\t\t\t\taccessorKey: 'priority',\n\t\t\t\theader: 'Priority',\n\t\t\t\tsorting: {\n\t\t\t\t\t// Custom sort function — refers to the table-level `sorting.fns` registry.\n\t\t\t\t\tfn: 'priorityRank',\n\t\t\t\t},\n\t\t\t},\n\t\t\t{\n\t\t\t\taccessorKey: 'rank',\n\t\t\t\theader: 'Rank',\n\t\t\t\tcell: { type: 'number' },\n\t\t\t\t// Lower rank = better, but the header still shows the natural ↑/↓ arrow.\n\t\t\t\tsorting: { invert: true },\n\t\t\t},\n\t\t\t{\n\t\t\t\taccessorKey: 'dueDate',\n\t\t\t\theader: 'Due',\n\t\t\t\tcell: { type: 'date' },\n\t\t\t\tsorting: { fn: 'datetime' },\n\t\t\t},\n\t\t\t{\n\t\t\t\taccessorKey: 'assignee',\n\t\t\t\theader: 'Assignee',\n\t\t\t\t// Push unassigned tasks to the bottom regardless of direction.\n\t\t\t\tsorting: { undefined: 'last' },\n\t\t\t},\n\t\t],\n\t\tsorting: {\n\t\t\t// Two-column default sort: critical first, then earliest due date.\n\t\t\tdefaultSorting: [\n\t\t\t\t{ id: 'priority', desc: false },\n\t\t\t\t{ id: 'dueDate', desc: false },\n\t\t\t],\n\t\t\t// Hold ⌘/Ctrl-click to extend; cap at 3 active sort columns.\n\t\t\tmulti: { max: 3, event: 'ctrl' },\n\t\t\t// Custom comparator addressable from `column.sorting.fn = 'priorityRank'`.\n\t\t\tfns: {\n\t\t\t\tpriorityRank: (rowA, rowB, columnId) => {\n\t\t\t\t\tconst a = (rowA as { getValue: (k: string) => Task['priority'] }).getValue(columnId)\n\t\t\t\t\tconst b = (rowB as { getValue: (k: string) => Task['priority'] }).getValue(columnId)\n\t\t\t\t\treturn PRIORITY_RANK[a] - PRIORITY_RANK[b]\n\t\t\t\t},\n\t\t\t},\n\t\t\t// Mirror sort state into the URL (or a server query).\n\t\t\tonChange: (sort) => {\n\t\t\t\tif (typeof window !== 'undefined') console.info('[sorting]', sort)\n\t\t\t},\n\t\t\ttoolbar: true,\n\t\t},\n\t})\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#64748b', fontSize: '0.875rem' }}>\n\t\t\t\tInitial sort is <strong>priority asc → due asc</strong>. Click headers to sort; hold <kbd>⌘</kbd>/<kbd>Ctrl</kbd>{' '}\n\t\t\t\tto add more columns (max 3). The <strong>Priority</strong> column uses a registered <code>priorityRank</code>{' '}\n\t\t\t\tcomparator, <strong>Rank</strong> is inverted (lower = better), and <strong>Assignee</strong> pushes empty\n\t\t\t\tvalues to the bottom.\n\t\t\t</p>\n\t\t\t<DataGrid table={table} />\n\t\t</div>\n\t)\n}\n",
  "sort-toolbar": "'use client'\n\nimport { DataGrid, useDataGrid } from 'shared/DataGrid'\n\ntype Employee = {\n\tid: number\n\tname: string\n\tdepartment: string\n\trole: string\n\tsalary: number\n\tstartDate: string\n}\n\nconst DATA: Employee[] = [\n\t{ id: 1, name: 'Alice Johnson', department: 'Engineering', role: 'Engineer', salary: 95000, startDate: '2021-03-15' },\n\t{ id: 2, name: 'Bob Smith', department: 'Design', role: 'Designer', salary: 85000, startDate: '2020-07-01' },\n\t{ id: 3, name: 'Carol White', department: 'Engineering', role: 'Manager', salary: 110000, startDate: '2019-01-10' },\n\t{ id: 4, name: 'David Brown', department: 'Finance', role: 'Analyst', salary: 90000, startDate: '2022-05-20' },\n\t{ id: 5, name: 'Eve Davis', department: 'Engineering', role: 'Engineer', salary: 100000, startDate: '2021-11-08' },\n\t{ id: 6, name: 'Frank Miller', department: 'Design', role: 'Designer', salary: 82000, startDate: '2023-02-14' },\n\t{ id: 7, name: 'Grace Kim', department: 'Engineering', role: 'Engineer', salary: 92000, startDate: '2022-09-03' },\n\t{ id: 8, name: 'Henry Adams', department: 'Finance', role: 'Manager', salary: 120000, startDate: '2018-04-22' },\n\t{ id: 9, name: 'Iris Chen', department: 'Design', role: 'Designer', salary: 78000, startDate: '2023-06-30' },\n\t{ id: 10, name: 'Jack Wilson', department: 'Engineering', role: 'Engineer', salary: 88000, startDate: '2022-01-15' },\n]\n\nexport function SortToolbarExample() {\n\tconst table = useDataGrid({\n\t\tdata: DATA,\n\t\tcolumns: [\n\t\t\t{ accessorKey: 'name', header: 'Name' },\n\t\t\t{ accessorKey: 'department', header: 'Department' },\n\t\t\t{ accessorKey: 'role', header: 'Role' },\n\t\t\t{ accessorKey: 'salary', header: 'Salary', cell: { type: 'number' } },\n\t\t\t{ accessorKey: 'startDate', header: 'Start Date', cell: { type: 'date' } },\n\t\t],\n\t\t// Enables Sort button in the toolbar — opens a popover to manage multi-sort\n\t\tsorting: { toolbar: true },\n\t})\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#64748b', fontSize: '0.875rem' }}>\n\t\t\t\tClick the <strong>Sort</strong> button in the toolbar to add sort entries (column + direction). Header clicks and\n\t\t\t\tthe popover share the same multi-sort state.\n\t\t\t</p>\n\t\t\t<DataGrid table={table} />\n\t\t</div>\n\t)\n}\n",
  "filter-operators": "'use client'\n\nimport { defineColumns } from '@ez-kit/data-grid-react'\nimport { useState } from 'react'\n\nimport { DataGrid, useDataGrid } from 'shared/DataGrid'\n\ntype Employee = {\n\tid: number\n\tname: string\n\tdepartment: string\n\tsalary: number\n\tjoinedAt: string\n\tactive: boolean\n}\n\nconst DATA: Employee[] = [\n\t{ id: 1, name: 'Alice Johnson', department: 'Engineering', salary: 95000, joinedAt: '2021-03-15', active: true },\n\t{ id: 2, name: 'Bob Smith', department: 'Marketing', salary: 72000, joinedAt: '2020-07-01', active: false },\n\t{ id: 3, name: 'Carol White', department: 'Engineering', salary: 105000, joinedAt: '2019-11-20', active: true },\n\t{ id: 4, name: 'Dave Brown', department: 'Sales', salary: 68000, joinedAt: '2022-01-10', active: true },\n\t{ id: 5, name: 'Eve Davis', department: 'Engineering', salary: 88000, joinedAt: '2021-08-05', active: true },\n\t{ id: 6, name: 'Frank Lee', department: 'Marketing', salary: 61000, joinedAt: '2023-04-18', active: false },\n\t{ id: 7, name: 'Grace Kim', department: 'Sales', salary: 77000, joinedAt: '2020-12-30', active: true },\n\t{ id: 8, name: 'Hank Patel', department: 'Engineering', salary: 115000, joinedAt: '2018-06-25', active: true },\n]\n\nconst textOperatorColumns = defineColumns<Employee>([\n\t{\n\t\taccessorKey: 'name',\n\t\theader: 'Name',\n\t\tfiltering: { operators: true },\n\t},\n\t{\n\t\taccessorKey: 'department',\n\t\theader: 'Department',\n\t\tfiltering: { operators: { items: ['contains', 'equals', 'isEmpty', 'isNotEmpty'] } },\n\t},\n])\n\nconst numberOperatorColumns = defineColumns<Employee>([\n\t{ accessorKey: 'name', header: 'Name' },\n\t{\n\t\taccessorKey: 'salary',\n\t\theader: 'Salary',\n\t\tcell: { type: 'number' },\n\t\tfiltering: { operators: true, defaultOperator: 'gte' },\n\t},\n])\n\nconst betweenInputsColumns = defineColumns<Employee>([\n\t{ accessorKey: 'name', header: 'Name' },\n\t{\n\t\taccessorKey: 'salary',\n\t\theader: 'Salary',\n\t\tcell: { type: 'number' },\n\t\tfiltering: {\n\t\t\toperators: {\n\t\t\t\titems: ['eq', 'between'],\n\t\t\t\tbetweenOperator: { variant: 'inputs' },\n\t\t\t},\n\t\t},\n\t},\n])\n\nconst betweenSliderColumns = defineColumns<Employee>([\n\t{ accessorKey: 'name', header: 'Name' },\n\t{\n\t\taccessorKey: 'salary',\n\t\theader: 'Salary',\n\t\tcell: { type: 'number' },\n\t\tfiltering: {\n\t\t\toperators: {\n\t\t\t\titems: ['eq', 'between'],\n\t\t\t\tbetweenOperator: { variant: 'slider', min: 50000, max: 130000 },\n\t\t\t},\n\t\t},\n\t},\n])\n\nconst dateOperatorColumns = defineColumns<Employee>([\n\t{ accessorKey: 'name', header: 'Name' },\n\t{\n\t\taccessorKey: 'joinedAt',\n\t\theader: 'Joined',\n\t\tcell: { type: 'date' },\n\t\tfiltering: { operators: true },\n\t},\n])\n\nconst dateBetweenColumns = defineColumns<Employee>([\n\t{ accessorKey: 'name', header: 'Name' },\n\t{\n\t\taccessorKey: 'joinedAt',\n\t\theader: 'Joined',\n\t\tcell: { type: 'date' },\n\t\tfiltering: {\n\t\t\toperators: {\n\t\t\t\titems: ['eq', 'before', 'after', 'between'],\n\t\t\t\tbetweenOperator: { variant: 'inputs' },\n\t\t\t},\n\t\t},\n\t},\n])\n\nfunction TextOperatorsDemo() {\n\tconst table = useDataGrid({ data: DATA, columns: textOperatorColumns, filtering: true })\n\treturn <DataGrid table={table} />\n}\n\nfunction NumberOperatorsDemo() {\n\tconst table = useDataGrid({ data: DATA, columns: numberOperatorColumns, filtering: true })\n\treturn <DataGrid table={table} />\n}\n\nfunction BetweenInputsDemo() {\n\tconst table = useDataGrid({ data: DATA, columns: betweenInputsColumns, filtering: true })\n\treturn <DataGrid table={table} />\n}\n\nfunction BetweenSliderDemo() {\n\tconst table = useDataGrid({ data: DATA, columns: betweenSliderColumns, filtering: true })\n\treturn <DataGrid table={table} />\n}\n\nfunction DateOperatorsDemo() {\n\tconst table = useDataGrid({ data: DATA, columns: dateOperatorColumns, filtering: true })\n\treturn <DataGrid table={table} />\n}\n\nfunction DateBetweenDemo() {\n\tconst table = useDataGrid({ data: DATA, columns: dateBetweenColumns, filtering: true })\n\treturn <DataGrid table={table} />\n}\n\nconst SUB_TABS = [\n\t{ id: 'text', label: 'Text operators', Component: TextOperatorsDemo },\n\t{ id: 'number', label: 'Number operators', Component: NumberOperatorsDemo },\n\t{ id: 'between-inputs', label: 'Between (inputs)', Component: BetweenInputsDemo },\n\t{ id: 'between-slider', label: 'Between (slider)', Component: BetweenSliderDemo },\n\t{ id: 'date', label: 'Date operators', Component: DateOperatorsDemo },\n\t{ id: 'date-between', label: 'Date between', Component: DateBetweenDemo },\n] as const\n\ntype SubTabId = (typeof SUB_TABS)[number]['id']\n\nexport function FilterOperatorsExample() {\n\tconst [active, setActive] = useState<SubTabId>('text')\n\tconst tab = SUB_TABS.find((t) => t.id === active) ?? SUB_TABS[0]\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#666' }}>\n\t\t\t\tDemonstrates per-column filter operators — text contains/equals/isEmpty, number comparisons, between with inputs\n\t\t\t\tand slider, and date operators.\n\t\t\t</p>\n\n\t\t\t<div\n\t\t\t\tstyle={{\n\t\t\t\t\tdisplay: 'flex',\n\t\t\t\t\tgap: '0.25rem',\n\t\t\t\t\tflexWrap: 'wrap',\n\t\t\t\t\tborderBottom: '1px solid #e2e8f0',\n\t\t\t\t\tmarginBottom: '1.5rem',\n\t\t\t\t}}\n\t\t\t>\n\t\t\t\t{SUB_TABS.map((t) => (\n\t\t\t\t\t<button\n\t\t\t\t\t\tkey={t.id}\n\t\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\t\tsetActive(t.id)\n\t\t\t\t\t\t}}\n\t\t\t\t\t\tstyle={{\n\t\t\t\t\t\t\tpadding: '0.375rem 0.75rem',\n\t\t\t\t\t\t\tborder: 'none',\n\t\t\t\t\t\t\tborderBottom: active === t.id ? '2px solid #0f172a' : '2px solid transparent',\n\t\t\t\t\t\t\tbackground: 'none',\n\t\t\t\t\t\t\tcursor: 'pointer',\n\t\t\t\t\t\t\tfontSize: '0.875rem',\n\t\t\t\t\t\t\tfontWeight: active === t.id ? 600 : 400,\n\t\t\t\t\t\t\tcolor: active === t.id ? '#0f172a' : '#64748b',\n\t\t\t\t\t\t\tmarginBottom: '-1px',\n\t\t\t\t\t\t}}\n\t\t\t\t\t>\n\t\t\t\t\t\t{t.label}\n\t\t\t\t\t</button>\n\t\t\t\t))}\n\t\t\t</div>\n\n\t\t\t<tab.Component />\n\t\t</div>\n\t)\n}\n",
  "filter-popover": "'use client'\n\nimport { defineColumns } from '@ez-kit/data-grid-react'\nimport { useState } from 'react'\n\nimport { DataGrid, useDataGrid } from 'shared/DataGrid'\n\ntype Employee = {\n\tid: number\n\tname: string\n\tdepartment: string\n\tsalary: number\n\tjoinedAt: string\n\tactive: boolean\n}\n\nconst DATA: Employee[] = [\n\t{ id: 1, name: 'Alice Johnson', department: 'Engineering', salary: 95000, joinedAt: '2021-03-15', active: true },\n\t{ id: 2, name: 'Bob Smith', department: 'Marketing', salary: 72000, joinedAt: '2020-07-01', active: false },\n\t{ id: 3, name: 'Carol White', department: 'Engineering', salary: 105000, joinedAt: '2019-11-20', active: true },\n\t{ id: 4, name: 'Dave Brown', department: 'Sales', salary: 68000, joinedAt: '2022-01-10', active: true },\n\t{ id: 5, name: 'Eve Davis', department: 'Engineering', salary: 88000, joinedAt: '2021-08-05', active: true },\n\t{ id: 6, name: 'Frank Lee', department: 'Marketing', salary: 61000, joinedAt: '2023-04-18', active: false },\n\t{ id: 7, name: 'Grace Kim', department: 'Sales', salary: 77000, joinedAt: '2020-12-30', active: true },\n\t{ id: 8, name: 'Hank Patel', department: 'Engineering', salary: 115000, joinedAt: '2018-06-25', active: true },\n]\n\nconst basicColumns = defineColumns<Employee>([\n\t{ accessorKey: 'name', header: 'Name' },\n\t{ accessorKey: 'department', header: 'Department' },\n\t{ accessorKey: 'salary', header: 'Salary', cell: { type: 'number' } },\n\t{ accessorKey: 'joinedAt', header: 'Joined', cell: { type: 'date' } },\n])\n\nconst withOperatorsColumns = defineColumns<Employee>([\n\t{\n\t\taccessorKey: 'name',\n\t\theader: 'Name',\n\t\tfiltering: { operators: true },\n\t},\n\t{\n\t\taccessorKey: 'department',\n\t\theader: 'Department',\n\t\tfiltering: { operators: { items: ['contains', 'equals', 'isEmpty', 'isNotEmpty'] } },\n\t},\n\t{\n\t\taccessorKey: 'salary',\n\t\theader: 'Salary',\n\t\tcell: { type: 'number' },\n\t\tfiltering: {\n\t\t\toperators: {\n\t\t\t\tbetweenOperator: { variant: 'slider', min: 50000, max: 130000 },\n\t\t\t},\n\t\t},\n\t},\n\t{\n\t\taccessorKey: 'joinedAt',\n\t\theader: 'Joined',\n\t\tcell: { type: 'date' },\n\t\tfiltering: { operators: true },\n\t},\n])\n\nfunction BasicDemo() {\n\tconst table = useDataGrid({\n\t\tdata: DATA,\n\t\tcolumns: basicColumns,\n\t\tfiltering: { variant: 'popover' },\n\t\tsorting: true,\n\t})\n\treturn <DataGrid table={table} />\n}\n\nfunction WithOperatorsDemo() {\n\tconst table = useDataGrid({\n\t\tdata: DATA,\n\t\tcolumns: withOperatorsColumns,\n\t\tfiltering: { variant: 'popover' },\n\t\tsorting: true,\n\t})\n\treturn <DataGrid table={table} />\n}\n\nconst SUB_TABS = [\n\t{ id: 'basic', label: 'Basic', Component: BasicDemo },\n\t{ id: 'with-operators', label: 'With operators', Component: WithOperatorsDemo },\n] as const\n\ntype SubTabId = (typeof SUB_TABS)[number]['id']\n\nexport function FilterPopoverExample() {\n\tconst [active, setActive] = useState<SubTabId>('basic')\n\tconst tab = SUB_TABS.find((t) => t.id === active) ?? SUB_TABS[0]\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#666' }}>\n\t\t\t\tA filter icon appears in each column header. Click it to open a popover with the filter input and operators. The\n\t\t\t\ticon turns primary colour when a filter is active.\n\t\t\t</p>\n\n\t\t\t<div\n\t\t\t\tstyle={{\n\t\t\t\t\tdisplay: 'flex',\n\t\t\t\t\tgap: '0.25rem',\n\t\t\t\t\tflexWrap: 'wrap',\n\t\t\t\t\tborderBottom: '1px solid #e2e8f0',\n\t\t\t\t\tmarginBottom: '1.5rem',\n\t\t\t\t}}\n\t\t\t>\n\t\t\t\t{SUB_TABS.map((t) => (\n\t\t\t\t\t<button\n\t\t\t\t\t\tkey={t.id}\n\t\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\t\tsetActive(t.id)\n\t\t\t\t\t\t}}\n\t\t\t\t\t\tstyle={{\n\t\t\t\t\t\t\tpadding: '0.375rem 0.75rem',\n\t\t\t\t\t\t\tborder: 'none',\n\t\t\t\t\t\t\tborderBottom: active === t.id ? '2px solid #0f172a' : '2px solid transparent',\n\t\t\t\t\t\t\tbackground: 'none',\n\t\t\t\t\t\t\tcursor: 'pointer',\n\t\t\t\t\t\t\tfontSize: '0.875rem',\n\t\t\t\t\t\t\tfontWeight: active === t.id ? 600 : 400,\n\t\t\t\t\t\t\tcolor: active === t.id ? '#0f172a' : '#64748b',\n\t\t\t\t\t\t\tmarginBottom: '-1px',\n\t\t\t\t\t\t}}\n\t\t\t\t\t>\n\t\t\t\t\t\t{t.label}\n\t\t\t\t\t</button>\n\t\t\t\t))}\n\t\t\t</div>\n\n\t\t\t<tab.Component />\n\t\t</div>\n\t)\n}\n",
  "global-filtering": "'use client'\n\nimport { defineColumns } from '@ez-kit/data-grid-react'\nimport { useMemo, useState } from 'react'\n\nimport { DataGrid, useDataGrid } from 'shared/DataGrid'\n\nimport { makeUsers, type User } from './_data'\n\nconst columnsWithSecret = defineColumns<User & { internalId: string }>([\n\t{ accessorKey: 'name', header: 'Name' },\n\t{ accessorKey: 'email', header: 'Email' },\n\t{ accessorKey: 'age', header: 'Age', cell: { type: 'number' } },\n\t{ accessorKey: 'internalId', header: 'Internal ID', globalFilter: false },\n])\n\nconst baseColumns = defineColumns<User>([\n\t{ accessorKey: 'name', header: 'Name' },\n\t{ accessorKey: 'email', header: 'Email' },\n\t{ accessorKey: 'age', header: 'Age', cell: { type: 'number' } },\n\t{ accessorKey: 'active', header: 'Active', cell: { type: 'boolean' } },\n])\n\nfunction makeUsersWithSecret(count: number) {\n\treturn makeUsers(count).map((u) => ({ ...u, internalId: `INT-${String(u.id).padStart(5, '0')}` }))\n}\n\nfunction BasicDemo() {\n\tconst data = useMemo(() => makeUsers(50), [])\n\tconst table = useDataGrid({\n\t\tdata,\n\t\tcolumns: baseColumns,\n\t\tglobalFiltering: true,\n\t\tpagination: { pageSize: 10 },\n\t})\n\treturn <DataGrid table={table} />\n}\n\nfunction CombinedDemo() {\n\tconst data = useMemo(() => makeUsers(50), [])\n\tconst table = useDataGrid({\n\t\tdata,\n\t\tcolumns: baseColumns,\n\t\tfiltering: true,\n\t\tglobalFiltering: { placeholder: 'Search users…' },\n\t\tpagination: { pageSize: 10 },\n\t})\n\treturn <DataGrid table={table} />\n}\n\nfunction ExcludedColumnDemo() {\n\tconst data = useMemo(() => makeUsersWithSecret(50), [])\n\tconst table = useDataGrid({\n\t\tdata,\n\t\tcolumns: columnsWithSecret,\n\t\tglobalFiltering: { placeholder: 'Try searching for INT-00001…' },\n\t\tpagination: { pageSize: 10 },\n\t})\n\treturn <DataGrid table={table} />\n}\n\nfunction CustomFnDemo() {\n\tconst data = useMemo(() => makeUsers(50), [])\n\tconst table = useDataGrid({\n\t\tdata,\n\t\tcolumns: baseColumns,\n\t\tglobalFiltering: {\n\t\t\tplaceholder: 'Starts-with search…',\n\t\t\tdebounce: 0,\n\t\t\tfn: (row, columnId, value) => {\n\t\t\t\tconst cell = String(row.getValue(columnId) ?? '').toLowerCase()\n\t\t\t\treturn cell.startsWith(String(value).toLowerCase())\n\t\t\t},\n\t\t},\n\t\tpagination: { pageSize: 10 },\n\t})\n\treturn <DataGrid table={table} />\n}\n\nconst SUB_TABS = [\n\t{ id: 'basic', label: 'Basic', Component: BasicDemo },\n\t{ id: 'combined', label: 'With column filters', Component: CombinedDemo },\n\t{ id: 'excluded', label: 'Exclude a column', Component: ExcludedColumnDemo },\n\t{ id: 'custom-fn', label: 'Custom filter fn', Component: CustomFnDemo },\n] as const\n\ntype SubTabId = (typeof SUB_TABS)[number]['id']\n\nexport function GlobalFilteringExample() {\n\tconst [active, setActive] = useState<SubTabId>('basic')\n\tconst tab = SUB_TABS.find((t) => t.id === active) ?? SUB_TABS[0]\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#666' }}>\n\t\t\t\tA search field appears in the right side of the toolbar. Typing into it filters rows across all searchable columns\n\t\t\t\twith a 250ms debounce by default.\n\t\t\t</p>\n\n\t\t\t<div\n\t\t\t\tstyle={{\n\t\t\t\t\tdisplay: 'flex',\n\t\t\t\t\tgap: '0.25rem',\n\t\t\t\t\tflexWrap: 'wrap',\n\t\t\t\t\tborderBottom: '1px solid #e2e8f0',\n\t\t\t\t\tmarginBottom: '1.5rem',\n\t\t\t\t}}\n\t\t\t>\n\t\t\t\t{SUB_TABS.map((t) => (\n\t\t\t\t\t<button\n\t\t\t\t\t\tkey={t.id}\n\t\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\t\tsetActive(t.id)\n\t\t\t\t\t\t}}\n\t\t\t\t\t\tstyle={{\n\t\t\t\t\t\t\tpadding: '0.375rem 0.75rem',\n\t\t\t\t\t\t\tborder: 'none',\n\t\t\t\t\t\t\tborderBottom: active === t.id ? '2px solid #0f172a' : '2px solid transparent',\n\t\t\t\t\t\t\tbackground: 'none',\n\t\t\t\t\t\t\tcursor: 'pointer',\n\t\t\t\t\t\t\tfontSize: '0.875rem',\n\t\t\t\t\t\t\tfontWeight: active === t.id ? 600 : 400,\n\t\t\t\t\t\t\tcolor: active === t.id ? '#0f172a' : '#64748b',\n\t\t\t\t\t\t\tmarginBottom: '-1px',\n\t\t\t\t\t\t}}\n\t\t\t\t\t>\n\t\t\t\t\t\t{t.label}\n\t\t\t\t\t</button>\n\t\t\t\t))}\n\t\t\t</div>\n\n\t\t\t<tab.Component />\n\t\t</div>\n\t)\n}\n",
  "filter-chips": "'use client'\n\nimport { defineColumns } from '@ez-kit/data-grid-react'\nimport { useMemo, useState } from 'react'\n\nimport { DataGrid, useDataGrid } from 'shared/DataGrid'\n\nimport { makeUsers, type User } from './_data'\n\nconst columns = defineColumns<User>([\n\t{ accessorKey: 'name', header: 'Name' },\n\t{ accessorKey: 'email', header: 'Email' },\n\t{ accessorKey: 'age', header: 'Age', cell: { type: 'number' } },\n\t{ accessorKey: 'active', header: 'Active', cell: { type: 'boolean' } },\n])\n\nfunction AutoMountDemo() {\n\tconst data = useMemo(() => makeUsers(50), [])\n\tconst table = useDataGrid({\n\t\tdata,\n\t\tcolumns,\n\t\tfiltering: { chips: true, clearButton: true },\n\t\tglobalFiltering: { placeholder: 'Search…' },\n\t\tpagination: { pageSize: 10 },\n\t})\n\treturn <DataGrid table={table} />\n}\n\nfunction AlwaysShowDemo() {\n\tconst data = useMemo(() => makeUsers(50), [])\n\tconst table = useDataGrid({\n\t\tdata,\n\t\tcolumns,\n\t\tfiltering: { chips: true, clearButton: { alwaysShow: true } },\n\t\tglobalFiltering: true,\n\t\tpagination: { pageSize: 10 },\n\t})\n\treturn <DataGrid table={table} />\n}\n\nfunction CustomLayoutDemo() {\n\tconst data = useMemo(() => makeUsers(50), [])\n\tconst table = useDataGrid({\n\t\tdata,\n\t\tcolumns,\n\t\tfiltering: true,\n\t\tglobalFiltering: true,\n\t\tpagination: { pageSize: 10 },\n\t})\n\treturn (\n\t\t<DataGrid table={table}>\n\t\t\t<DataGrid.Toolbar>\n\t\t\t\t<DataGrid.GlobalFilterInput />\n\t\t\t\t<DataGrid.ClearFiltersButton>Reset</DataGrid.ClearFiltersButton>\n\t\t\t</DataGrid.Toolbar>\n\t\t\t<div\n\t\t\t\tstyle={{\n\t\t\t\t\tdisplay: 'flex',\n\t\t\t\t\talignItems: 'center',\n\t\t\t\t\tgap: '0.5rem',\n\t\t\t\t\tpadding: '0.5rem 0',\n\t\t\t\t\tflexWrap: 'wrap',\n\t\t\t\t}}\n\t\t\t>\n\t\t\t\t<span style={{ color: '#64748b', fontSize: '0.875rem' }}>Active:</span>\n\t\t\t\t<DataGrid.ActiveFiltersBar />\n\t\t\t</div>\n\t\t\t<DataGrid.Table />\n\t\t\t<DataGrid.Pagination />\n\t\t</DataGrid>\n\t)\n}\n\nconst SUB_TABS = [\n\t{ id: 'auto', label: 'Auto-mount', Component: AutoMountDemo },\n\t{ id: 'always', label: 'Always show clear', Component: AlwaysShowDemo },\n\t{ id: 'custom', label: 'Custom layout', Component: CustomLayoutDemo },\n] as const\n\ntype SubTabId = (typeof SUB_TABS)[number]['id']\n\nexport function FilterChipsExample() {\n\tconst [active, setActive] = useState<SubTabId>('auto')\n\tconst tab = SUB_TABS.find((t) => t.id === active) ?? SUB_TABS[0]\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#666' }}>\n\t\t\t\tActive filter chips and a Clear-all button are both opt-in via{' '}\n\t\t\t\t<code>{`filtering: { chips, clearButton }`}</code>. Both compound members are also available for custom\n\t\t\t\tlayouts.\n\t\t\t</p>\n\n\t\t\t<div\n\t\t\t\tstyle={{\n\t\t\t\t\tdisplay: 'flex',\n\t\t\t\t\tgap: '0.25rem',\n\t\t\t\t\tflexWrap: 'wrap',\n\t\t\t\t\tborderBottom: '1px solid #e2e8f0',\n\t\t\t\t\tmarginBottom: '1.5rem',\n\t\t\t\t}}\n\t\t\t>\n\t\t\t\t{SUB_TABS.map((t) => (\n\t\t\t\t\t<button\n\t\t\t\t\t\tkey={t.id}\n\t\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\t\tsetActive(t.id)\n\t\t\t\t\t\t}}\n\t\t\t\t\t\tstyle={{\n\t\t\t\t\t\t\tpadding: '0.375rem 0.75rem',\n\t\t\t\t\t\t\tborder: 'none',\n\t\t\t\t\t\t\tborderBottom: active === t.id ? '2px solid #0f172a' : '2px solid transparent',\n\t\t\t\t\t\t\tbackground: 'none',\n\t\t\t\t\t\t\tcursor: 'pointer',\n\t\t\t\t\t\t\tfontSize: '0.875rem',\n\t\t\t\t\t\t\tfontWeight: active === t.id ? 600 : 400,\n\t\t\t\t\t\t\tcolor: active === t.id ? '#0f172a' : '#64748b',\n\t\t\t\t\t\t\tmarginBottom: '-1px',\n\t\t\t\t\t\t}}\n\t\t\t\t\t>\n\t\t\t\t\t\t{t.label}\n\t\t\t\t\t</button>\n\t\t\t\t))}\n\t\t\t</div>\n\n\t\t\t<tab.Component />\n\t\t</div>\n\t)\n}\n",
  "filter-multi-value": "'use client'\n\nimport { defineColumns } from '@ez-kit/data-grid-react'\nimport { useState } from 'react'\n\nimport { DataGrid, useDataGrid } from 'shared/DataGrid'\n\ntype Ticket = {\n\tid: number\n\ttitle: string\n\tstatus: 'open' | 'in_progress' | 'done' | 'cancelled'\n\tpriority: 'low' | 'medium' | 'high'\n}\n\nconst DATA: Ticket[] = [\n\t{ id: 1, title: 'Indexing job hangs on large datasets', status: 'open', priority: 'high' },\n\t{ id: 2, title: 'Add dark theme toggle', status: 'in_progress', priority: 'medium' },\n\t{ id: 3, title: 'Fix 500 on /metrics', status: 'done', priority: 'high' },\n\t{ id: 4, title: 'Tighten Stripe webhook auth', status: 'open', priority: 'high' },\n\t{ id: 5, title: 'Rewrite onboarding tour', status: 'in_progress', priority: 'low' },\n\t{ id: 6, title: 'Drop unused legacy endpoints', status: 'cancelled', priority: 'low' },\n\t{ id: 7, title: 'Email digest opt-out flag', status: 'done', priority: 'medium' },\n\t{ id: 8, title: 'Add quick filters to /tickets', status: 'open', priority: 'medium' },\n\t{ id: 9, title: 'Run lighthouse on every PR', status: 'in_progress', priority: 'low' },\n\t{ id: 10, title: 'Replace usage chart library', status: 'done', priority: 'medium' },\n]\n\nconst STATUS_ITEMS = [\n\t{ value: 'open', label: 'Open' },\n\t{ value: 'in_progress', label: 'In progress' },\n\t{ value: 'done', label: 'Done' },\n\t{ value: 'cancelled', label: 'Cancelled' },\n]\n\nconst PRIORITY_ITEMS = [\n\t{ value: 'low', label: 'Low' },\n\t{ value: 'medium', label: 'Medium' },\n\t{ value: 'high', label: 'High' },\n]\n\nconst baseColumns = defineColumns<Ticket>([\n\t{ accessorKey: 'title', header: 'Title' },\n\t{\n\t\taccessorKey: 'status',\n\t\theader: 'Status',\n\t\tcell: { type: 'select', config: { items: STATUS_ITEMS } },\n\t\tfiltering: { operators: true },\n\t},\n\t{\n\t\taccessorKey: 'priority',\n\t\theader: 'Priority',\n\t\tcell: { type: 'badge', config: { items: PRIORITY_ITEMS } },\n\t\tfiltering: { operators: true },\n\t},\n])\n\nconst notInColumns = defineColumns<Ticket>([\n\t{ accessorKey: 'title', header: 'Title' },\n\t{\n\t\taccessorKey: 'status',\n\t\theader: 'Status',\n\t\tcell: { type: 'select', config: { items: STATUS_ITEMS } },\n\t\tfiltering: { operators: true, defaultOperator: 'notIn' },\n\t},\n])\n\nfunction InDefaultsDemo() {\n\tconst table = useDataGrid({ data: DATA, columns: baseColumns, filtering: true })\n\treturn <DataGrid table={table} />\n}\n\nfunction FacetedCountsDemo() {\n\tconst table = useDataGrid({\n\t\tdata: DATA,\n\t\tcolumns: baseColumns,\n\t\tfiltering: { faceted: true },\n\t})\n\treturn <DataGrid table={table} />\n}\n\nfunction NotInDemo() {\n\tconst table = useDataGrid({ data: DATA, columns: notInColumns, filtering: true })\n\treturn <DataGrid table={table} />\n}\n\nconst SUB_TABS = [\n\t{ id: 'in', label: 'In (default)', Component: InDefaultsDemo },\n\t{ id: 'faceted', label: 'Faceted counts', Component: FacetedCountsDemo },\n\t{ id: 'not-in', label: 'Not in', Component: NotInDemo },\n] as const\n\ntype SubTabId = (typeof SUB_TABS)[number]['id']\n\nexport function FilterMultiValueExample() {\n\tconst [active, setActive] = useState<SubTabId>('in')\n\tconst tab = SUB_TABS.find((t) => t.id === active) ?? SUB_TABS[0]\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#666' }}>\n\t\t\t\tMulti-value filters for <code>select</code> and <code>badge</code> columns — pick any combination of values to\n\t\t\t\tnarrow the table. With <code>filtering: {'{'} faceted: true {'}'}</code> each option also shows how many rows\n\t\t\t\twould remain when selected.\n\t\t\t</p>\n\n\t\t\t<div\n\t\t\t\tstyle={{\n\t\t\t\t\tdisplay: 'flex',\n\t\t\t\t\tgap: '0.25rem',\n\t\t\t\t\tflexWrap: 'wrap',\n\t\t\t\t\tborderBottom: '1px solid #e2e8f0',\n\t\t\t\t\tmarginBottom: '1.5rem',\n\t\t\t\t}}\n\t\t\t>\n\t\t\t\t{SUB_TABS.map((t) => (\n\t\t\t\t\t<button\n\t\t\t\t\t\tkey={t.id}\n\t\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\t\tsetActive(t.id)\n\t\t\t\t\t\t}}\n\t\t\t\t\t\tstyle={{\n\t\t\t\t\t\t\tpadding: '0.375rem 0.75rem',\n\t\t\t\t\t\t\tborder: 'none',\n\t\t\t\t\t\t\tborderBottom: active === t.id ? '2px solid #0f172a' : '2px solid transparent',\n\t\t\t\t\t\t\tbackground: 'none',\n\t\t\t\t\t\t\tcursor: 'pointer',\n\t\t\t\t\t\t\tfontSize: '0.875rem',\n\t\t\t\t\t\t\tfontWeight: active === t.id ? 600 : 400,\n\t\t\t\t\t\t\tcolor: active === t.id ? '#0f172a' : '#64748b',\n\t\t\t\t\t\t\tmarginBottom: '-1px',\n\t\t\t\t\t\t}}\n\t\t\t\t\t>\n\t\t\t\t\t\t{t.label}\n\t\t\t\t\t</button>\n\t\t\t\t))}\n\t\t\t</div>\n\n\t\t\t<tab.Component />\n\t\t</div>\n\t)\n}\n",
  "filter-date-range": "'use client'\n\nimport { defineColumns } from '@ez-kit/data-grid-react'\nimport { useState } from 'react'\n\nimport { DataGrid, useDataGrid } from 'shared/DataGrid'\n\nimport type { DateRangePreset } from '@ez-kit/data-grid-react'\n\ntype Release = {\n\tid: number\n\ttitle: string\n\treleasedAt: string\n}\n\nconst DATA: Release[] = [\n\t{ id: 1, title: 'v1.0.0 — initial release', releasedAt: '2025-11-04' },\n\t{ id: 2, title: 'v1.1.0 — column pinning', releasedAt: '2025-12-18' },\n\t{ id: 3, title: 'v1.2.0 — global filtering', releasedAt: '2026-02-09' },\n\t{ id: 4, title: 'v1.3.0 — between slider', releasedAt: '2026-03-21' },\n\t{ id: 5, title: 'v1.4.0 — multi-value filters', releasedAt: '2026-04-12' },\n\t{ id: 6, title: 'v1.5.0 — date range presets', releasedAt: '2026-05-14' },\n]\n\nconst presetsBuiltInColumns = defineColumns<Release>([\n\t{ accessorKey: 'title', header: 'Title' },\n\t{\n\t\taccessorKey: 'releasedAt',\n\t\theader: 'Released',\n\t\tcell: { type: 'date' },\n\t\tfiltering: {\n\t\t\toperators: {\n\t\t\t\titems: ['eq', 'before', 'after', 'between'],\n\t\t\t\tbetweenOperator: { variant: 'inputs', presets: true },\n\t\t\t},\n\t\t\tdefaultOperator: 'between',\n\t\t},\n\t},\n])\n\nconst calendarColumns = defineColumns<Release>([\n\t{ accessorKey: 'title', header: 'Title' },\n\t{\n\t\taccessorKey: 'releasedAt',\n\t\theader: 'Released',\n\t\tcell: { type: 'date' },\n\t\tfiltering: {\n\t\t\toperators: {\n\t\t\t\titems: ['between'],\n\t\t\t\tbetweenOperator: { variant: 'calendar', presets: true },\n\t\t\t},\n\t\t\tdefaultOperator: 'between',\n\t\t},\n\t},\n])\n\nconst customPresets: DateRangePreset[] = [\n\t{\n\t\tid: 'q1-2026',\n\t\tlabel: 'Q1 2026',\n\t\tgetRange: () => ({ from: '2026-01-01', to: '2026-03-31' }),\n\t},\n\t{\n\t\tid: 'q2-2026',\n\t\tlabel: 'Q2 2026',\n\t\tgetRange: () => ({ from: '2026-04-01', to: '2026-06-30' }),\n\t},\n\t{\n\t\tid: 'all-2025',\n\t\tlabel: 'All of 2025',\n\t\tgetRange: () => ({ from: '2025-01-01', to: '2025-12-31' }),\n\t},\n]\n\nconst customPresetsColumns = defineColumns<Release>([\n\t{ accessorKey: 'title', header: 'Title' },\n\t{\n\t\taccessorKey: 'releasedAt',\n\t\theader: 'Released',\n\t\tcell: { type: 'date' },\n\t\tfiltering: {\n\t\t\toperators: {\n\t\t\t\titems: ['between'],\n\t\t\t\tbetweenOperator: { variant: 'inputs', presets: customPresets },\n\t\t\t},\n\t\t\tdefaultOperator: 'between',\n\t\t},\n\t},\n])\n\nfunction BuiltInPresetsDemo() {\n\tconst table = useDataGrid({ data: DATA, columns: presetsBuiltInColumns, filtering: true })\n\treturn <DataGrid table={table} />\n}\n\nfunction CalendarRangeDemo() {\n\tconst table = useDataGrid({ data: DATA, columns: calendarColumns, filtering: true })\n\treturn <DataGrid table={table} />\n}\n\nfunction CustomPresetsDemo() {\n\tconst table = useDataGrid({ data: DATA, columns: customPresetsColumns, filtering: true })\n\treturn <DataGrid table={table} />\n}\n\nconst SUB_TABS = [\n\t{ id: 'built-in', label: 'Built-in presets', Component: BuiltInPresetsDemo },\n\t{ id: 'calendar', label: 'Range calendar', Component: CalendarRangeDemo },\n\t{ id: 'custom', label: 'Custom presets', Component: CustomPresetsDemo },\n] as const\n\ntype SubTabId = (typeof SUB_TABS)[number]['id']\n\nexport function FilterDateRangeExample() {\n\tconst [active, setActive] = useState<SubTabId>('built-in')\n\tconst tab = SUB_TABS.find((t) => t.id === active) ?? SUB_TABS[0]\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#666' }}>\n\t\t\t\tDate range filters: built-in presets (Today, Yesterday, Last 7/30 days, This/Last month), a true range\n\t\t\t\tcalendar via <code>variant: &apos;calendar&apos;</code>, and custom presets — quarterly ranges, year-long windows, or\n\t\t\t\tanything else that fits your domain.\n\t\t\t</p>\n\n\t\t\t<div\n\t\t\t\tstyle={{\n\t\t\t\t\tdisplay: 'flex',\n\t\t\t\t\tgap: '0.25rem',\n\t\t\t\t\tflexWrap: 'wrap',\n\t\t\t\t\tborderBottom: '1px solid #e2e8f0',\n\t\t\t\t\tmarginBottom: '1.5rem',\n\t\t\t\t}}\n\t\t\t>\n\t\t\t\t{SUB_TABS.map((t) => (\n\t\t\t\t\t<button\n\t\t\t\t\t\tkey={t.id}\n\t\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\t\tsetActive(t.id)\n\t\t\t\t\t\t}}\n\t\t\t\t\t\tstyle={{\n\t\t\t\t\t\t\tpadding: '0.375rem 0.75rem',\n\t\t\t\t\t\t\tborder: 'none',\n\t\t\t\t\t\t\tborderBottom: active === t.id ? '2px solid #0f172a' : '2px solid transparent',\n\t\t\t\t\t\t\tbackground: 'none',\n\t\t\t\t\t\t\tcursor: 'pointer',\n\t\t\t\t\t\t\tfontSize: '0.875rem',\n\t\t\t\t\t\t\tfontWeight: active === t.id ? 600 : 400,\n\t\t\t\t\t\t\tcolor: active === t.id ? '#0f172a' : '#64748b',\n\t\t\t\t\t\t\tmarginBottom: '-1px',\n\t\t\t\t\t\t}}\n\t\t\t\t\t>\n\t\t\t\t\t\t{t.label}\n\t\t\t\t\t</button>\n\t\t\t\t))}\n\t\t\t</div>\n\n\t\t\t<tab.Component />\n\t\t</div>\n\t)\n}\n",
  "filter-panel": "'use client'\n\nimport { defineColumns } from '@ez-kit/data-grid-react'\n\nimport { DataGrid, useDataGrid } from 'shared/DataGrid'\n\ntype Order = {\n\tid: number\n\tcustomer: string\n\tstatus: 'open' | 'shipped' | 'delivered' | 'cancelled'\n\ttotal: number\n\tplacedAt: string\n}\n\nconst DATA: Order[] = [\n\t{ id: 1001, customer: 'Acme Inc.', status: 'open', total: 1280, placedAt: '2026-05-12' },\n\t{ id: 1002, customer: 'Globex Corp.', status: 'shipped', total: 875, placedAt: '2026-05-10' },\n\t{ id: 1003, customer: 'Initech', status: 'delivered', total: 410, placedAt: '2026-05-08' },\n\t{ id: 1004, customer: 'Umbrella Co.', status: 'cancelled', total: 220, placedAt: '2026-04-28' },\n\t{ id: 1005, customer: 'Stark Industries', status: 'open', total: 3120, placedAt: '2026-05-11' },\n\t{ id: 1006, customer: 'Wayne Enterprises', status: 'shipped', total: 1990, placedAt: '2026-05-09' },\n\t{ id: 1007, customer: 'Hooli', status: 'delivered', total: 660, placedAt: '2026-04-30' },\n\t{ id: 1008, customer: 'Pied Piper', status: 'open', total: 145, placedAt: '2026-05-14' },\n]\n\nconst STATUS_ITEMS = [\n\t{ value: 'open', label: 'Open' },\n\t{ value: 'shipped', label: 'Shipped' },\n\t{ value: 'delivered', label: 'Delivered' },\n\t{ value: 'cancelled', label: 'Cancelled' },\n]\n\nconst COLUMNS = defineColumns<Order>([\n\t{\n\t\taccessorKey: 'customer',\n\t\theader: 'Customer',\n\t\tfiltering: { operators: true },\n\t},\n\t{\n\t\taccessorKey: 'status',\n\t\theader: 'Status',\n\t\tcell: { type: 'select', config: { items: STATUS_ITEMS } },\n\t\tfiltering: { operators: true },\n\t},\n\t{\n\t\taccessorKey: 'total',\n\t\theader: 'Total',\n\t\tcell: { type: 'number' },\n\t\tfiltering: {\n\t\t\toperators: {\n\t\t\t\titems: ['eq', 'between'],\n\t\t\t\tbetweenOperator: { variant: 'slider', min: 0, max: 5000 },\n\t\t\t},\n\t\t\tdefaultOperator: 'between',\n\t\t},\n\t},\n\t{\n\t\taccessorKey: 'placedAt',\n\t\theader: 'Placed',\n\t\tcell: { type: 'date' },\n\t\tfiltering: {\n\t\t\toperators: {\n\t\t\t\titems: ['between'],\n\t\t\t\tbetweenOperator: { variant: 'inputs', presets: true },\n\t\t\t},\n\t\t\tdefaultOperator: 'between',\n\t\t},\n\t},\n])\n\nexport function FilterPanelExample() {\n\tconst table = useDataGrid({\n\t\tdata: DATA,\n\t\tcolumns: COLUMNS,\n\t\tfiltering: { variant: 'panel', faceted: true },\n\t})\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#666' }}>\n\t\t\t\tPanel variant — все column-фильтры собраны в одну строку чипов вместо шапки. Каждый чип показывает{' '}\n\t\t\t\t<code>label: value</code> (или <code>Any</code> если пусто), клик открывает popover с инпутом, X очищает.\n\t\t\t\tHeader теряет inline-фильтры, но остаётся sortable.\n\t\t\t</p>\n\n\t\t\t<DataGrid table={table}>\n\t\t\t\t<DataGrid.Toolbar />\n\t\t\t\t<DataGrid.FilterPanel />\n\t\t\t\t<DataGrid.Table />\n\t\t\t\t<DataGrid.Pagination />\n\t\t\t</DataGrid>\n\t\t</div>\n\t)\n}\n",
  "selection-bar": "'use client'\n\nimport { useState } from 'react'\n\nimport { DataGrid, useDataGrid } from 'shared/DataGrid'\n\nimport { columns, INITIAL_DATA } from './_data'\n\nexport function SelectionBarExample() {\n\tconst [data, setData] = useState(INITIAL_DATA)\n\tconst [log, setLog] = useState<string[]>([])\n\n\tconst addLog = (msg: string) => {\n\t\tsetLog((prev) => [`${new Date().toLocaleTimeString()} — ${msg}`, ...prev].slice(0, 5))\n\t}\n\n\tconst table = useDataGrid({\n\t\tdata,\n\t\tcolumns,\n\t\tsorting: true,\n\t\tpagination: { pageSize: 10 },\n\t\tselection: true,\n\t\tselectionBar: {\n\t\t\tonDelete: ({ selectedRows, clearSelection }) => {\n\t\t\t\tconst names = selectedRows.map((r) => r.original.name).join(', ')\n\t\t\t\tsetData((prev) => prev.filter((row) => !selectedRows.some((r) => r.original === row)))\n\t\t\t\tclearSelection()\n\t\t\t\taddLog(`Deleted: ${names}`)\n\t\t\t},\n\t\t\tonClear: ({ clearSelection }) => {\n\t\t\t\tclearSelection()\n\t\t\t\taddLog('Selection cleared')\n\t\t\t},\n\t\t\tactions: (\n\t\t\t\t<button\n\t\t\t\t\ttype='button'\n\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\taddLog('Export triggered')\n\t\t\t\t\t}}\n\t\t\t\t\tstyle={{\n\t\t\t\t\t\tpadding: '0 10px',\n\t\t\t\t\t\theight: 28,\n\t\t\t\t\t\tfontSize: 12,\n\t\t\t\t\t\tborder: '1px solid #e2e8f0',\n\t\t\t\t\t\tborderRadius: 6,\n\t\t\t\t\t\tbackground: 'white',\n\t\t\t\t\t\tcursor: 'pointer',\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\tExport\n\t\t\t\t</button>\n\t\t\t),\n\t\t},\n\t})\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#666' }}>\n\t\t\t\tSelect rows to reveal the selection bar. Supports Delete, custom actions slot, and Cancel.\n\t\t\t</p>\n\n\t\t\t<DataGrid table={table} />\n\n\t\t\t{log.length > 0 && (\n\t\t\t\t<div\n\t\t\t\t\tstyle={{\n\t\t\t\t\t\tmarginTop: '1.5rem',\n\t\t\t\t\t\tpadding: '0.75rem 1rem',\n\t\t\t\t\t\tbackground: '#f8fafc',\n\t\t\t\t\t\tborder: '1px solid #e2e8f0',\n\t\t\t\t\t\tborderRadius: 8,\n\t\t\t\t\t\tfontSize: 13,\n\t\t\t\t\t\tcolor: '#475569',\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\t<div style={{ fontWeight: 600, marginBottom: '0.5rem', color: '#0f172a' }}>Action log</div>\n\t\t\t\t\t{log.map((entry, i) => (\n\t\t\t\t\t\t<div key={i}>{entry}</div>\n\t\t\t\t\t))}\n\t\t\t\t</div>\n\t\t\t)}\n\t\t</div>\n\t)\n}\n",
  "selection-bar-inline": "'use client'\n\nimport { useState } from 'react'\n\nimport { DataGrid, useDataGrid } from 'shared/DataGrid'\n\nimport { columns, INITIAL_DATA } from './_data'\n\nexport function SelectionBarInlineExample() {\n\tconst [data, setData] = useState(INITIAL_DATA)\n\tconst [log, setLog] = useState<string[]>([])\n\n\tconst addLog = (msg: string) => {\n\t\tsetLog((prev) => [`${new Date().toLocaleTimeString()} — ${msg}`, ...prev].slice(0, 5))\n\t}\n\n\tconst table = useDataGrid({\n\t\tdata,\n\t\tcolumns,\n\t\tsorting: true,\n\t\tpagination: { pageSize: 10 },\n\t\tselection: true,\n\t\tselectionBar: {\n\t\t\tvariant: 'inline',\n\t\t\tonDelete: ({ selectedRows, clearSelection }) => {\n\t\t\t\tconst names = selectedRows.map((r) => r.original.name).join(', ')\n\t\t\t\tsetData((prev) => prev.filter((row) => !selectedRows.some((r) => r.original === row)))\n\t\t\t\tclearSelection()\n\t\t\t\taddLog(`Deleted: ${names}`)\n\t\t\t},\n\t\t\tonClear: ({ clearSelection }) => {\n\t\t\t\tclearSelection()\n\t\t\t\taddLog('Selection cleared')\n\t\t\t},\n\t\t\tactions: (\n\t\t\t\t<button\n\t\t\t\t\ttype='button'\n\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\taddLog('Export triggered')\n\t\t\t\t\t}}\n\t\t\t\t\tstyle={{\n\t\t\t\t\t\tpadding: '0 10px',\n\t\t\t\t\t\theight: 28,\n\t\t\t\t\t\tfontSize: 12,\n\t\t\t\t\t\tborder: '1px solid #e2e8f0',\n\t\t\t\t\t\tborderRadius: 6,\n\t\t\t\t\t\tbackground: 'white',\n\t\t\t\t\t\tcursor: 'pointer',\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\tExport\n\t\t\t\t</button>\n\t\t\t),\n\t\t},\n\t})\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#666' }}>\n\t\t\t\tInline variant — selection bar renders as a normal block above the Toolbar, without overlay or\n\t\t\t\tpositioning. No animation, instant show/hide.\n\t\t\t</p>\n\n\t\t\t<DataGrid table={table} />\n\n\t\t\t{log.length > 0 && (\n\t\t\t\t<div\n\t\t\t\t\tstyle={{\n\t\t\t\t\t\tmarginTop: '1.5rem',\n\t\t\t\t\t\tpadding: '0.75rem 1rem',\n\t\t\t\t\t\tbackground: '#f8fafc',\n\t\t\t\t\t\tborder: '1px solid #e2e8f0',\n\t\t\t\t\t\tborderRadius: 8,\n\t\t\t\t\t\tfontSize: 13,\n\t\t\t\t\t\tcolor: '#475569',\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\t<div style={{ fontWeight: 600, marginBottom: '0.5rem', color: '#0f172a' }}>Action log</div>\n\t\t\t\t\t{log.map((entry, i) => (\n\t\t\t\t\t\t<div key={i}>{entry}</div>\n\t\t\t\t\t))}\n\t\t\t\t</div>\n\t\t\t)}\n\t\t</div>\n\t)\n}\n",
  "delete-confirmation": "'use client'\n\nimport { defineColumns } from '@ez-kit/data-grid-react'\nimport { useState } from 'react'\n\nimport { DataGrid, useDataGrid } from 'shared/DataGrid'\n\nimport { PRODUCT_DATA, type Product } from './_data'\n\nconst columns = defineColumns<Product>([\n\t{ accessorKey: 'name', header: 'Name' },\n\t{ accessorKey: 'category', header: 'Category' },\n\t{ accessorKey: 'status', header: 'Status' },\n\t{ accessorKey: 'stock', header: 'Stock' },\n])\n\nexport function DeleteConfirmationExample() {\n\tconst [data, setData] = useState(PRODUCT_DATA)\n\n\tconst table = useDataGrid({\n\t\tdata,\n\t\tcolumns,\n\t\tsorting: true,\n\t\tpagination: { pageSize: 10 },\n\t\tdeleting: {\n\t\t\tonDelete: ({ row }) => {\n\t\t\t\tsetData((prev) => prev.filter((item) => item.id !== row.original.id))\n\t\t\t},\n\t\t\tconfirmation: {\n\t\t\t\ttitle: 'Delete product?',\n\t\t\t\tdescription: (row) =>\n\t\t\t\t\t`Are you sure you want to delete \"${(row.original as Product).name}\"? This action cannot be undone.`,\n\t\t\t},\n\t\t},\n\t})\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#666' }}>\n\t\t\t\tClick Delete on any row — a confirmation dialog will appear before the row is removed.\n\t\t\t</p>\n\t\t\t<DataGrid table={table} />\n\t\t</div>\n\t)\n}\n",
  "column-visibility": "'use client'\n\nimport { DataGrid, useDataGrid } from 'shared/DataGrid'\n\ntype Employee = {\n\tid: number\n\tname: string\n\temail: string\n\trole: string\n\tdepartment: string\n\tsalary: number\n\tstartDate: string\n}\n\nconst DATA: Employee[] = [\n\t{\n\t\tid: 1,\n\t\tname: 'Alice Johnson',\n\t\temail: 'alice@example.com',\n\t\trole: 'Engineer',\n\t\tdepartment: 'Engineering',\n\t\tsalary: 95000,\n\t\tstartDate: '2021-03-15',\n\t},\n\t{\n\t\tid: 2,\n\t\tname: 'Bob Smith',\n\t\temail: 'bob@example.com',\n\t\trole: 'Designer',\n\t\tdepartment: 'Design',\n\t\tsalary: 85000,\n\t\tstartDate: '2020-07-01',\n\t},\n\t{\n\t\tid: 3,\n\t\tname: 'Carol White',\n\t\temail: 'carol@example.com',\n\t\trole: 'Manager',\n\t\tdepartment: 'Engineering',\n\t\tsalary: 110000,\n\t\tstartDate: '2019-01-10',\n\t},\n\t{\n\t\tid: 4,\n\t\tname: 'David Brown',\n\t\temail: 'david@example.com',\n\t\trole: 'Analyst',\n\t\tdepartment: 'Finance',\n\t\tsalary: 90000,\n\t\tstartDate: '2022-05-20',\n\t},\n\t{\n\t\tid: 5,\n\t\tname: 'Eve Davis',\n\t\temail: 'eve@example.com',\n\t\trole: 'Engineer',\n\t\tdepartment: 'Engineering',\n\t\tsalary: 100000,\n\t\tstartDate: '2021-11-08',\n\t},\n\t{\n\t\tid: 6,\n\t\tname: 'Frank Miller',\n\t\temail: 'frank@example.com',\n\t\trole: 'Designer',\n\t\tdepartment: 'Design',\n\t\tsalary: 82000,\n\t\tstartDate: '2023-02-14',\n\t},\n]\n\nexport function ColumnVisibilityExample() {\n\tconst table = useDataGrid({\n\t\tdata: DATA,\n\t\tcolumns: [\n\t\t\t{\n\t\t\t\taccessorKey: 'name',\n\t\t\t\theader: 'Name',\n\t\t\t\t// visibility: true — required column, always visible / locked (no Hide option in menu)\n\t\t\t\tvisibility: true,\n\t\t\t},\n\t\t\t{\n\t\t\t\taccessorKey: 'email',\n\t\t\t\theader: 'Email',\n\t\t\t},\n\t\t\t{\n\t\t\t\taccessorKey: 'role',\n\t\t\t\theader: 'Role',\n\t\t\t},\n\t\t\t{\n\t\t\t\taccessorKey: 'department',\n\t\t\t\theader: 'Department',\n\t\t\t},\n\t\t\t{\n\t\t\t\taccessorKey: 'salary',\n\t\t\t\theader: 'Salary',\n\t\t\t\tcell: { type: 'number' },\n\t\t\t\t// starts hidden, user can toggle it on via the Columns button\n\t\t\t\tvisibility: { defaultHidden: true },\n\t\t\t},\n\t\t\t{\n\t\t\t\taccessorKey: 'startDate',\n\t\t\t\theader: 'Start Date',\n\t\t\t\tcell: { type: 'date' },\n\t\t\t\t// starts hidden, user can toggle it on via the Columns button\n\t\t\t\tvisibility: { defaultHidden: true },\n\t\t\t},\n\t\t],\n\t\tsorting: true,\n\t\t// shows the \"Columns\" toggle button in the toolbar\n\t\tcolumnVisibility: { toolbar: true },\n\t})\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#64748b', fontSize: '0.875rem' }}>\n\t\t\t\t<strong>Name</strong> column is locked (cannot be hidden). <strong>Salary</strong> and{' '}\n\t\t\t\t<strong>Start Date</strong> are hidden by default. Use the <strong>Columns</strong> button or the column menu\n\t\t\t\t(⋯) to toggle visibility.\n\t\t\t</p>\n\t\t\t<DataGrid table={table} />\n\t\t</div>\n\t)\n}\n",
  "column-pinning": "'use client'\n\nimport { defineColumns } from '@ez-kit/data-grid-react'\nimport { useState } from 'react'\n\nimport { DataGrid, useDataGrid } from 'shared/DataGrid'\n\nimport { PRODUCT_DATA, type Product } from './_data'\n\nconst colPinColumns = defineColumns<Product>([\n\t{ accessorKey: 'name', header: 'Name', size: 180, pinning: { defaultPin: 'left' } },\n\t{\n\t\taccessorKey: 'status',\n\t\theader: 'Status',\n\t\tsize: 120,\n\t\tcell: {\n\t\t\ttype: 'badge',\n\t\t\tconfig: {\n\t\t\t\titems: [\n\t\t\t\t\t{ value: 'active', label: 'Active', variant: 'default' },\n\t\t\t\t\t{ value: 'inactive', label: 'Inactive', variant: 'secondary' },\n\t\t\t\t\t{ value: 'discontinued', label: 'Discontinued', variant: 'destructive' },\n\t\t\t\t],\n\t\t\t},\n\t\t},\n\t},\n\t{ accessorKey: 'category', header: 'Category', size: 140 },\n\t{\n\t\taccessorKey: 'image',\n\t\theader: 'Image',\n\t\tsize: 80,\n\t\tcell: { type: 'image', config: { width: 40, height: 40, alt: 'Product' } },\n\t},\n\t{ accessorKey: 'website', header: 'Website', size: 220, cell: { type: 'link' } },\n\t{\n\t\taccessorKey: 'stock',\n\t\theader: 'Stock %',\n\t\tsize: 120,\n\t\tcell: { type: 'progress', config: { max: 100 } },\n\t\tpinning: { defaultPin: 'right' },\n\t},\n])\n\nexport function ColumnPinningExample() {\n\tconst [data] = useState(PRODUCT_DATA)\n\n\tconst table = useDataGrid({\n\t\tdata,\n\t\tcolumns: colPinColumns,\n\t\tsorting: true,\n\t\tpinning: { column: true },\n\t})\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#666' }}>\n\t\t\t\tClick ⋮ next to a column header to pin left / right or unpin. Scroll horizontally to see pin shadows.\n\t\t\t</p>\n\t\t\t<DataGrid table={table} />\n\t\t</div>\n\t)\n}\n",
  "resizing": "'use client'\n\nimport { useState } from 'react'\n\nimport { DataGrid, useDataGrid } from 'shared/DataGrid'\n\nimport { INITIAL_DATA, resizableColumns } from './_data'\n\nexport function ResizingExample() {\n\tconst [data] = useState(INITIAL_DATA)\n\n\tconst onChange = useDataGrid({\n\t\tdata,\n\t\tcolumns: resizableColumns,\n\t\tsorting: true,\n\t\tsizing: { mode: 'onChange' },\n\t})\n\n\tconst onEnd = useDataGrid({\n\t\tdata,\n\t\tcolumns: resizableColumns,\n\t\tsorting: true,\n\t\tsizing: { mode: 'onEnd' },\n\t})\n\n\treturn (\n\t\t<div>\n\t\t\t<h2 style={{ marginTop: 0, marginBottom: '0.5rem' }}>onChange</h2>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#666' }}>\n\t\t\t\tDrag column borders to resize. Double-click to reset. &quot;Active&quot; column has resizing disabled.\n\t\t\t</p>\n\t\t\t<DataGrid table={onChange} />\n\n\t\t\t<h2 style={{ marginTop: '3rem', marginBottom: '0.5rem' }}>onEnd (performant)</h2>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#666' }}>\n\t\t\t\tWidth updates only after mouse release. No re-renders during drag.\n\t\t\t</p>\n\t\t\t<DataGrid table={onEnd} />\n\t\t</div>\n\t)\n}\n",
  "columns-combined": "'use client'\n\nimport { defineColumns } from '@ez-kit/data-grid-react'\nimport { useState } from 'react'\n\nimport { DataGrid, useDataGrid } from 'shared/DataGrid'\n\nimport { INITIAL_DATA, type User } from '../_data'\n\nconst combinedColumns = defineColumns<User>([\n\t{\n\t\taccessorKey: 'name',\n\t\theader: 'Name',\n\t\tsize: 200,\n\t\tminSize: 80,\n\t\tmaxSize: 400,\n\t\tpinning: { defaultPin: 'left' },\n\t},\n\t{ accessorKey: 'email', header: 'Email', size: 250, minSize: 120 },\n\t{\n\t\taccessorKey: 'age',\n\t\theader: 'Age',\n\t\tsize: 80,\n\t\tminSize: 50,\n\t\tmaxSize: 150,\n\t\tcell: { type: 'number' },\n\t},\n\t{\n\t\taccessorKey: 'active',\n\t\theader: 'Active',\n\t\tsize: 100,\n\t\tenableResizing: false,\n\t\tcell: { type: 'boolean' },\n\t\tpinning: { defaultPin: 'right' },\n\t\tvisibility: { defaultHidden: true },\n\t},\n])\n\nexport function ColumnsCombinedExample() {\n\tconst [data] = useState<User[]>(INITIAL_DATA)\n\n\tconst table = useDataGrid({\n\t\tdata,\n\t\tcolumns: combinedColumns,\n\t\tsorting: true,\n\t\tcolumnVisibility: { toolbar: true },\n\t\tpinning: { column: true },\n\t\tsizing: { mode: 'onEnd' },\n\t})\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#64748b', fontSize: '0.875rem' }}>\n\t\t\t\tVisibility, pinning and resizing combined. Drag column borders to resize. Pin a column via the ⋮ menu. Toggle\n\t\t\t\tcolumns through the <strong>Columns</strong> button. <strong>Active</strong> starts hidden.\n\t\t\t</p>\n\t\t\t<DataGrid table={table} />\n\t\t</div>\n\t)\n}\n",
  "column-helper": "'use client'\n\nimport { createColumnHelper } from '@ez-kit/data-grid-react'\nimport { useState } from 'react'\n\nimport { CustomDataGrid, useDataGrid } from 'shared/data-grid/CustomGrid'\n\nimport type { ColumnDef } from '@ez-kit/data-grid-react'\n\n// ── data ─────────────────────────────────────────────────────────────────────\n\ntype Employee = {\n\tid: number\n\tname: string\n\tdepartment: string\n\tscore: number\n\tactive: boolean\n\trating: number\n}\n\nconst EMPLOYEE_DATA: Employee[] = [\n\t{ id: 1, name: 'Alice Johnson', department: 'Engineering', score: 78, active: true, rating: 5 },\n\t{ id: 2, name: 'Bob Smith', department: 'Design', score: 45, active: false, rating: 3 },\n\t{ id: 3, name: 'Carol White', department: 'Marketing', score: 92, active: true, rating: 4 },\n\t{ id: 4, name: 'Dave Brown', department: 'Engineering', score: 60, active: true, rating: 2 },\n\t{ id: 5, name: 'Eve Davis', department: 'Sales', score: 88, active: false, rating: 5 },\n]\n\n// ── Example 1: base createColumnHelper (built-in types) ───────────────────────\n\nconst baseHelper = createColumnHelper<Employee>()\n\nconst baseColumns = [\n\tbaseHelper.text({ accessorKey: 'name', header: 'Name' }),\n\tbaseHelper.text({ accessorKey: 'department', header: 'Department' }),\n\tbaseHelper.progress({ accessorKey: 'score', header: 'Score %', config: { max: 100 } }),\n\tbaseHelper.boolean({ accessorKey: 'active', header: 'Active' }),\n]\n\nexport function ColumnHelperBaseExample() {\n\tconst [data] = useState(EMPLOYEE_DATA)\n\tconst table = useDataGrid({ data, columns: baseColumns, sorting: true })\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#666' }}>\n\t\t\t\tBuilt-in types via <code>createColumnHelper&lt;Employee&gt;()</code>.\n\t\t\t</p>\n\t\t\t<CustomDataGrid table={table} />\n\t\t</div>\n\t)\n}\n\n// ── Example 2: custom() — inherit type, override view ────────────────────────\n\nfunction StarRatingView({ value }: { value: unknown }) {\n\tconst count = typeof value === 'number' ? value : 0\n\treturn (\n\t\t<span style={{ color: '#f59e0b', letterSpacing: 2 }}>\n\t\t\t{'★'.repeat(count)}\n\t\t\t{'☆'.repeat(5 - count)}\n\t\t</span>\n\t)\n}\n\nconst customViewHelper = createColumnHelper<Employee>()\n\nconst customViewColumns = [\n\tcustomViewHelper.text({ accessorKey: 'name', header: 'Name' }),\n\tcustomViewHelper.text({ accessorKey: 'department', header: 'Department' }),\n\tcustomViewHelper.custom({\n\t\taccessorKey: 'rating',\n\t\theader: 'Rating',\n\t\ttype: 'number',\n\t\tview: StarRatingView,\n\t}),\n]\n\nexport function ColumnHelperCustomViewExample() {\n\tconst [data] = useState(EMPLOYEE_DATA)\n\tconst table = useDataGrid({ data, columns: customViewColumns, sorting: true })\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#666' }}>\n\t\t\t\t<code>helper.custom()</code> inherits <code>number</code> type behavior with a custom star-rating view.\n\t\t\t</p>\n\t\t\t<CustomDataGrid table={table} />\n\t\t</div>\n\t)\n}\n\n// ── Example 3: registered custom types (from extendDataGrid) ─────────────────\n\n// The custom grid registers 'rating' and 'color' via extendDataGrid().\n// Passing both type params gives type-safe named methods on the helper.\nconst registeredHelper = createColumnHelper<Employee, 'rating' | 'color'>(['rating', 'color'])\n\nconst registeredColumns = [\n\tregisteredHelper.text({ accessorKey: 'name', header: 'Name' }),\n\tregisteredHelper.text({ accessorKey: 'department', header: 'Department' }),\n\tregisteredHelper.rating({ accessorKey: 'rating', header: 'Rating' }),\n]\n\nexport function ColumnHelperRegisteredExample() {\n\tconst [data] = useState(EMPLOYEE_DATA)\n\tconst table = useDataGrid({ data, columns: registeredColumns as ColumnDef<Employee>[], sorting: true })\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#666' }}>\n\t\t\t\tNamed method <code>helper.rating()</code> for a type registered via <code>extendDataGrid()</code>.\n\t\t\t</p>\n\t\t\t<CustomDataGrid table={table} />\n\t\t</div>\n\t)\n}\n",
  "column-helper-custom-view": "'use client'\n\nimport { createColumnHelper } from '@ez-kit/data-grid-react'\nimport { useState } from 'react'\n\nimport { CustomDataGrid, useDataGrid } from 'shared/data-grid/CustomGrid'\n\nimport type { ColumnDef } from '@ez-kit/data-grid-react'\n\n// ── data ─────────────────────────────────────────────────────────────────────\n\ntype Employee = {\n\tid: number\n\tname: string\n\tdepartment: string\n\tscore: number\n\tactive: boolean\n\trating: number\n}\n\nconst EMPLOYEE_DATA: Employee[] = [\n\t{ id: 1, name: 'Alice Johnson', department: 'Engineering', score: 78, active: true, rating: 5 },\n\t{ id: 2, name: 'Bob Smith', department: 'Design', score: 45, active: false, rating: 3 },\n\t{ id: 3, name: 'Carol White', department: 'Marketing', score: 92, active: true, rating: 4 },\n\t{ id: 4, name: 'Dave Brown', department: 'Engineering', score: 60, active: true, rating: 2 },\n\t{ id: 5, name: 'Eve Davis', department: 'Sales', score: 88, active: false, rating: 5 },\n]\n\n// ── Example 1: base createColumnHelper (built-in types) ───────────────────────\n\nconst baseHelper = createColumnHelper<Employee>()\n\nconst baseColumns = [\n\tbaseHelper.text({ accessorKey: 'name', header: 'Name' }),\n\tbaseHelper.text({ accessorKey: 'department', header: 'Department' }),\n\tbaseHelper.progress({ accessorKey: 'score', header: 'Score %', config: { max: 100 } }),\n\tbaseHelper.boolean({ accessorKey: 'active', header: 'Active' }),\n]\n\nexport function ColumnHelperBaseExample() {\n\tconst [data] = useState(EMPLOYEE_DATA)\n\tconst table = useDataGrid({ data, columns: baseColumns, sorting: true })\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#666' }}>\n\t\t\t\tBuilt-in types via <code>createColumnHelper&lt;Employee&gt;()</code>.\n\t\t\t</p>\n\t\t\t<CustomDataGrid table={table} />\n\t\t</div>\n\t)\n}\n\n// ── Example 2: custom() — inherit type, override view ────────────────────────\n\nfunction StarRatingView({ value }: { value: unknown }) {\n\tconst count = typeof value === 'number' ? value : 0\n\treturn (\n\t\t<span style={{ color: '#f59e0b', letterSpacing: 2 }}>\n\t\t\t{'★'.repeat(count)}\n\t\t\t{'☆'.repeat(5 - count)}\n\t\t</span>\n\t)\n}\n\nconst customViewHelper = createColumnHelper<Employee>()\n\nconst customViewColumns = [\n\tcustomViewHelper.text({ accessorKey: 'name', header: 'Name' }),\n\tcustomViewHelper.text({ accessorKey: 'department', header: 'Department' }),\n\tcustomViewHelper.custom({\n\t\taccessorKey: 'rating',\n\t\theader: 'Rating',\n\t\ttype: 'number',\n\t\tview: StarRatingView,\n\t}),\n]\n\nexport function ColumnHelperCustomViewExample() {\n\tconst [data] = useState(EMPLOYEE_DATA)\n\tconst table = useDataGrid({ data, columns: customViewColumns, sorting: true })\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#666' }}>\n\t\t\t\t<code>helper.custom()</code> inherits <code>number</code> type behavior with a custom star-rating view.\n\t\t\t</p>\n\t\t\t<CustomDataGrid table={table} />\n\t\t</div>\n\t)\n}\n\n// ── Example 3: registered custom types (from extendDataGrid) ─────────────────\n\n// The custom grid registers 'rating' and 'color' via extendDataGrid().\n// Passing both type params gives type-safe named methods on the helper.\nconst registeredHelper = createColumnHelper<Employee, 'rating' | 'color'>(['rating', 'color'])\n\nconst registeredColumns = [\n\tregisteredHelper.text({ accessorKey: 'name', header: 'Name' }),\n\tregisteredHelper.text({ accessorKey: 'department', header: 'Department' }),\n\tregisteredHelper.rating({ accessorKey: 'rating', header: 'Rating' }),\n]\n\nexport function ColumnHelperRegisteredExample() {\n\tconst [data] = useState(EMPLOYEE_DATA)\n\tconst table = useDataGrid({ data, columns: registeredColumns as ColumnDef<Employee>[], sorting: true })\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#666' }}>\n\t\t\t\tNamed method <code>helper.rating()</code> for a type registered via <code>extendDataGrid()</code>.\n\t\t\t</p>\n\t\t\t<CustomDataGrid table={table} />\n\t\t</div>\n\t)\n}\n",
  "column-helper-registered": "'use client'\n\nimport { createColumnHelper } from '@ez-kit/data-grid-react'\nimport { useState } from 'react'\n\nimport { CustomDataGrid, useDataGrid } from 'shared/data-grid/CustomGrid'\n\nimport type { ColumnDef } from '@ez-kit/data-grid-react'\n\n// ── data ─────────────────────────────────────────────────────────────────────\n\ntype Employee = {\n\tid: number\n\tname: string\n\tdepartment: string\n\tscore: number\n\tactive: boolean\n\trating: number\n}\n\nconst EMPLOYEE_DATA: Employee[] = [\n\t{ id: 1, name: 'Alice Johnson', department: 'Engineering', score: 78, active: true, rating: 5 },\n\t{ id: 2, name: 'Bob Smith', department: 'Design', score: 45, active: false, rating: 3 },\n\t{ id: 3, name: 'Carol White', department: 'Marketing', score: 92, active: true, rating: 4 },\n\t{ id: 4, name: 'Dave Brown', department: 'Engineering', score: 60, active: true, rating: 2 },\n\t{ id: 5, name: 'Eve Davis', department: 'Sales', score: 88, active: false, rating: 5 },\n]\n\n// ── Example 1: base createColumnHelper (built-in types) ───────────────────────\n\nconst baseHelper = createColumnHelper<Employee>()\n\nconst baseColumns = [\n\tbaseHelper.text({ accessorKey: 'name', header: 'Name' }),\n\tbaseHelper.text({ accessorKey: 'department', header: 'Department' }),\n\tbaseHelper.progress({ accessorKey: 'score', header: 'Score %', config: { max: 100 } }),\n\tbaseHelper.boolean({ accessorKey: 'active', header: 'Active' }),\n]\n\nexport function ColumnHelperBaseExample() {\n\tconst [data] = useState(EMPLOYEE_DATA)\n\tconst table = useDataGrid({ data, columns: baseColumns, sorting: true })\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#666' }}>\n\t\t\t\tBuilt-in types via <code>createColumnHelper&lt;Employee&gt;()</code>.\n\t\t\t</p>\n\t\t\t<CustomDataGrid table={table} />\n\t\t</div>\n\t)\n}\n\n// ── Example 2: custom() — inherit type, override view ────────────────────────\n\nfunction StarRatingView({ value }: { value: unknown }) {\n\tconst count = typeof value === 'number' ? value : 0\n\treturn (\n\t\t<span style={{ color: '#f59e0b', letterSpacing: 2 }}>\n\t\t\t{'★'.repeat(count)}\n\t\t\t{'☆'.repeat(5 - count)}\n\t\t</span>\n\t)\n}\n\nconst customViewHelper = createColumnHelper<Employee>()\n\nconst customViewColumns = [\n\tcustomViewHelper.text({ accessorKey: 'name', header: 'Name' }),\n\tcustomViewHelper.text({ accessorKey: 'department', header: 'Department' }),\n\tcustomViewHelper.custom({\n\t\taccessorKey: 'rating',\n\t\theader: 'Rating',\n\t\ttype: 'number',\n\t\tview: StarRatingView,\n\t}),\n]\n\nexport function ColumnHelperCustomViewExample() {\n\tconst [data] = useState(EMPLOYEE_DATA)\n\tconst table = useDataGrid({ data, columns: customViewColumns, sorting: true })\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#666' }}>\n\t\t\t\t<code>helper.custom()</code> inherits <code>number</code> type behavior with a custom star-rating view.\n\t\t\t</p>\n\t\t\t<CustomDataGrid table={table} />\n\t\t</div>\n\t)\n}\n\n// ── Example 3: registered custom types (from extendDataGrid) ─────────────────\n\n// The custom grid registers 'rating' and 'color' via extendDataGrid().\n// Passing both type params gives type-safe named methods on the helper.\nconst registeredHelper = createColumnHelper<Employee, 'rating' | 'color'>(['rating', 'color'])\n\nconst registeredColumns = [\n\tregisteredHelper.text({ accessorKey: 'name', header: 'Name' }),\n\tregisteredHelper.text({ accessorKey: 'department', header: 'Department' }),\n\tregisteredHelper.rating({ accessorKey: 'rating', header: 'Rating' }),\n]\n\nexport function ColumnHelperRegisteredExample() {\n\tconst [data] = useState(EMPLOYEE_DATA)\n\tconst table = useDataGrid({ data, columns: registeredColumns as ColumnDef<Employee>[], sorting: true })\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#666' }}>\n\t\t\t\tNamed method <code>helper.rating()</code> for a type registered via <code>extendDataGrid()</code>.\n\t\t\t</p>\n\t\t\t<CustomDataGrid table={table} />\n\t\t</div>\n\t)\n}\n",
  "cell-types": "'use client'\n\nimport { useState } from 'react'\n\nimport { DataGrid, useDataGrid } from 'shared/DataGrid'\n\nimport { PRODUCT_DATA, productColumns, type Product } from './_data'\n\nexport function CellTypesExample() {\n\tconst [data, setData] = useState(PRODUCT_DATA)\n\n\tconst table = useDataGrid({\n\t\tdata,\n\t\tcolumns: productColumns,\n\t\tsorting: true,\n\t\tfiltering: true,\n\t\tpagination: { pageSize: 10 },\n\t\tediting: {\n\t\t\tmode: 'row',\n\t\t\tonSave: ({ rowId, values }) => {\n\t\t\t\tsetData((prev) => prev.map((row) => (row.id.toString() === rowId ? { ...row, ...values } : row)))\n\t\t\t},\n\t\t},\n\t\tcreating: {\n\t\t\tmode: 'pin-row',\n\t\t\tonSave: ({ values }) => {\n\t\t\t\tsetData((prev) => [...prev, values as Product])\n\t\t\t},\n\t\t},\n\t})\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#666' }}>\n\t\t\t\tDemonstrates select, badge, image, link, and progress cell types with editing and filtering.\n\t\t\t</p>\n\t\t\t<DataGrid table={table} />\n\t\t</div>\n\t)\n}\n",
  "custom-cell-types": "'use client'\n\nimport { defineColumns } from '@ez-kit/data-grid-react'\nimport { useState } from 'react'\n\nimport { CustomDataGrid, useDataGrid } from 'shared/data-grid/CustomGrid'\n\ntype Employee = {\n\tid: number\n\tname: string\n\tdepartment: string\n\trating: number\n\tfavoriteColor: string\n}\n\nconst EMPLOYEE_DATA: Employee[] = [\n\t{ id: 1, name: 'Alice Johnson', department: 'Engineering', rating: 5, favoriteColor: '#6366f1' },\n\t{ id: 2, name: 'Bob Smith', department: 'Design', rating: 3, favoriteColor: '#ec4899' },\n\t{ id: 3, name: 'Carol White', department: 'Marketing', rating: 4, favoriteColor: '#10b981' },\n\t{ id: 4, name: 'Dave Brown', department: 'Engineering', rating: 2, favoriteColor: '#f59e0b' },\n\t{ id: 5, name: 'Eve Davis', department: 'Sales', rating: 5, favoriteColor: '#3b82f6' },\n]\n\nconst employeeColumns = defineColumns<Employee>([\n\t{ accessorKey: 'name', header: 'Name' },\n\t{ accessorKey: 'department', header: 'Department' },\n\t{ accessorKey: 'rating', header: 'Rating', cell: { type: 'rating' } },\n\t{ accessorKey: 'favoriteColor', header: 'Color', cell: { type: 'color' } },\n])\n\nexport function CustomCellTypesExample() {\n\tconst [data, setData] = useState(EMPLOYEE_DATA)\n\n\tconst table = useDataGrid({\n\t\tdata,\n\t\tcolumns: employeeColumns,\n\t\tsorting: true,\n\t\tediting: {\n\t\t\tmode: 'row',\n\t\t\tonSave: ({ rowId, values }) => {\n\t\t\t\tsetData((prev) => prev.map((row) => (row.id.toString() === rowId ? { ...row, ...values } : row)))\n\t\t\t},\n\t\t},\n\t})\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#666' }}>\n\t\t\t\tCustom <code>rating</code> and <code>color</code> cell types added via <code>extendDataGrid()</code>. Click Edit\n\t\t\t\ton any row to try the custom inputs.\n\t\t\t</p>\n\t\t\t<CustomDataGrid table={table} />\n\t\t</div>\n\t)\n}\n",
  "date-cell": "'use client'\n\nimport { defineColumns } from '@ez-kit/data-grid-react'\nimport { useState } from 'react'\n\nimport { DataGrid, useDataGrid } from 'shared/DataGrid'\n\ntype Milestone = {\n\tid: number\n\ttitle: string\n\tdueDate: string\n\tcompletedAt: string | undefined\n}\n\nconst INITIAL_DATA: Milestone[] = [\n\t{ id: 1, title: 'Design review', dueDate: '2026-01-15', completedAt: '2026-01-12' },\n\t{ id: 2, title: 'API contract freeze', dueDate: '2026-02-01', completedAt: undefined },\n\t{ id: 3, title: 'Beta rollout', dueDate: '2026-03-10', completedAt: undefined },\n\t{ id: 4, title: 'Security audit', dueDate: '2025-11-20', completedAt: '2025-12-04' },\n\t{ id: 5, title: 'GA release', dueDate: '2026-05-01', completedAt: undefined },\n\t{ id: 6, title: 'Retrospective', dueDate: '2026-05-15', completedAt: undefined },\n]\n\nconst baseColumns = defineColumns<Milestone>([\n\t{ accessorKey: 'title', header: 'Title' },\n\t{\n\t\taccessorKey: 'dueDate',\n\t\theader: 'Due date',\n\t\tcell: {\n\t\t\ttype: 'date',\n\t\t\tconfig: { format: { dateStyle: 'medium' }, minValue: '2025-01-01', maxValue: '2027-12-31' },\n\t\t},\n\t\tfiltering: { operators: true },\n\t},\n\t{\n\t\taccessorKey: 'completedAt',\n\t\theader: 'Completed at',\n\t\tcell: {\n\t\t\ttype: 'date',\n\t\t\tconfig: { format: { dateStyle: 'short' } },\n\t\t},\n\t\tfiltering: {\n\t\t\toperators: {\n\t\t\t\titems: ['eq', 'before', 'after', 'between'],\n\t\t\t\tbetweenOperator: { variant: 'inputs' },\n\t\t\t},\n\t\t},\n\t},\n])\n\nfunction ViewOnlyDemo() {\n\tconst table = useDataGrid({ data: INITIAL_DATA, columns: baseColumns, filtering: true })\n\treturn <DataGrid table={table} />\n}\n\nfunction InlineEditDemo() {\n\tconst [rows, setRows] = useState<Milestone[]>(INITIAL_DATA)\n\tconst table = useDataGrid({\n\t\tdata: rows,\n\t\tcolumns: baseColumns,\n\t\tgetRowId: (row) => String(row.id),\n\t\tfiltering: true,\n\t\tediting: {\n\t\t\tmode: 'cell',\n\t\t\tonSave: ({ rowId, values }) => {\n\t\t\t\tsetRows((prev) => prev.map((row) => (String(row.id) === rowId ? { ...row, ...values } : row)))\n\t\t\t},\n\t\t},\n\t})\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '0.75rem', color: '#64748b', fontSize: '0.875rem' }}>\n\t\t\t\tDouble-click a date cell to open the picker. Both columns round-trip ISO 8601 strings.\n\t\t\t</p>\n\t\t\t<DataGrid table={table} />\n\t\t</div>\n\t)\n}\n\nfunction CreatingDemo() {\n\tconst [rows, setRows] = useState<Milestone[]>(INITIAL_DATA)\n\tconst table = useDataGrid({\n\t\tdata: rows,\n\t\tcolumns: baseColumns,\n\t\tgetRowId: (row) => String(row.id),\n\t\tcreating: {\n\t\t\tmode: 'row',\n\t\t\tonSave: ({ values }) => {\n\t\t\t\tconst next = values as Partial<Omit<Milestone, 'id'>>\n\t\t\t\tsetRows((prev) => [\n\t\t\t\t\t...prev,\n\t\t\t\t\t{\n\t\t\t\t\t\tid: prev.length + 1,\n\t\t\t\t\t\ttitle: next.title ?? '',\n\t\t\t\t\t\tdueDate: next.dueDate ?? '',\n\t\t\t\t\t\tcompletedAt: next.completedAt,\n\t\t\t\t\t},\n\t\t\t\t])\n\t\t\t},\n\t\t},\n\t})\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '0.75rem', color: '#64748b', fontSize: '0.875rem' }}>\n\t\t\t\tThe inline create row reuses the same DatePicker for the `creating` slot — `minValue` / `maxValue` from\n\t\t\t\t`DateCellConfig` clamp the calendar.\n\t\t\t</p>\n\t\t\t<DataGrid table={table} />\n\t\t</div>\n\t)\n}\n\nconst SUB_TABS = [\n\t{ id: 'view', label: 'View + formatting', Component: ViewOnlyDemo },\n\t{ id: 'edit', label: 'Inline edit', Component: InlineEditDemo },\n\t{ id: 'create', label: 'Creating', Component: CreatingDemo },\n] as const\n\ntype SubTabId = (typeof SUB_TABS)[number]['id']\n\nexport function DateCellExample() {\n\tconst [active, setActive] = useState<SubTabId>('view')\n\tconst tab = SUB_TABS.find((t) => t.id === active) ?? SUB_TABS[0]\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#64748b', fontSize: '0.875rem' }}>\n\t\t\t\tDemonstrates the `date` cell type end-to-end — view formatting via{' '}\n\t\t\t\t<code style={{ background: '#f1f5f9', padding: '0 0.25rem', borderRadius: 4 }}>Intl.DateTimeFormat</code>{' '}\n\t\t\t\toptions, inline cell editing, inline row creating, and per-column filter operators (including a\n\t\t\t\tdate-aware `between`).\n\t\t\t</p>\n\n\t\t\t<div\n\t\t\t\tstyle={{\n\t\t\t\t\tdisplay: 'flex',\n\t\t\t\t\tgap: '0.25rem',\n\t\t\t\t\tflexWrap: 'wrap',\n\t\t\t\t\tborderBottom: '1px solid #e2e8f0',\n\t\t\t\t\tmarginBottom: '1.5rem',\n\t\t\t\t}}\n\t\t\t>\n\t\t\t\t{SUB_TABS.map((t) => (\n\t\t\t\t\t<button\n\t\t\t\t\t\tkey={t.id}\n\t\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\t\tsetActive(t.id)\n\t\t\t\t\t\t}}\n\t\t\t\t\t\tstyle={{\n\t\t\t\t\t\t\tpadding: '0.375rem 0.75rem',\n\t\t\t\t\t\t\tborder: 'none',\n\t\t\t\t\t\t\tborderBottom: active === t.id ? '2px solid #0f172a' : '2px solid transparent',\n\t\t\t\t\t\t\tbackground: 'none',\n\t\t\t\t\t\t\tcursor: 'pointer',\n\t\t\t\t\t\t\tfontSize: '0.875rem',\n\t\t\t\t\t\t\tfontWeight: active === t.id ? 600 : 400,\n\t\t\t\t\t\t\tcolor: active === t.id ? '#0f172a' : '#64748b',\n\t\t\t\t\t\t\tmarginBottom: '-1px',\n\t\t\t\t\t\t}}\n\t\t\t\t\t>\n\t\t\t\t\t\t{t.label}\n\t\t\t\t\t</button>\n\t\t\t\t))}\n\t\t\t</div>\n\n\t\t\t<tab.Component />\n\t\t</div>\n\t)\n}\n",
  "creating": "'use client'\n\nimport { useState } from 'react'\n\nimport { Tabs, TabsList, TabsTrigger } from '@/components/ui/tabs'\n\nimport { CreatingModalExample } from './CreatingModalExample'\nimport { CreatingPinRowExample } from './CreatingPinRowExample'\nimport { CreatingRowExample } from './CreatingRowExample'\n\nconst SUB_TABS = [\n\t{ id: 'row', label: 'Row', Component: CreatingRowExample },\n\t{ id: 'modal', label: 'Modal', Component: CreatingModalExample },\n\t{ id: 'pin-row', label: 'Pin Row', Component: CreatingPinRowExample },\n] as const\n\ntype SubTabId = (typeof SUB_TABS)[number]['id']\n\nexport function CreatingExample() {\n\tconst [active, setActive] = useState<SubTabId>('row')\n\tconst tab = SUB_TABS.find((t) => t.id === active) ?? SUB_TABS[0]\n\n\treturn (\n\t\t<div>\n\t\t\t<p className='mb-4 text-sm text-muted-foreground'>\n\t\t\t\tDemonstrates the three creating modes: inline row, modal dialog, and pinned row.\n\t\t\t</p>\n\n\t\t\t<div className='mb-6 overflow-x-auto'>\n\t\t\t\t<Tabs\n\t\t\t\t\tvalue={active}\n\t\t\t\t\tonValueChange={(value) => {\n\t\t\t\t\t\tsetActive(value as SubTabId)\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\t<TabsList variant='line'>\n\t\t\t\t\t\t{SUB_TABS.map((t) => (\n\t\t\t\t\t\t\t<TabsTrigger\n\t\t\t\t\t\t\t\tkey={t.id}\n\t\t\t\t\t\t\t\tvalue={t.id}\n\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\t{t.label}\n\t\t\t\t\t\t\t</TabsTrigger>\n\t\t\t\t\t\t))}\n\t\t\t\t\t</TabsList>\n\t\t\t\t</Tabs>\n\t\t\t</div>\n\n\t\t\t<tab.Component />\n\t\t</div>\n\t)\n}\n",
  "creating-validation": "'use client'\n\nimport { ValidationError } from '@ez-kit/data-grid-react'\nimport { useState } from 'react'\nimport { z } from 'zod'\n\nimport { DataGrid, useDataGrid } from 'shared/DataGrid'\n\nimport { columns, INITIAL_DATA, type User } from '../_data'\n\nconst userSchema = z.object({\n\tname: z.string().min(2, 'must be at least 2 chars'),\n\temail: z.email('must be a valid email'),\n\tage: z\n\t\t.number({ message: 'age is required' })\n\t\t.int('must be a whole number')\n\t\t.min(18, 'must be 18 or older')\n\t\t.max(120, 'must be ≤120'),\n})\n\nexport function CreatingValidationExample() {\n\tconst [data, setData] = useState(INITIAL_DATA)\n\tconst [serverShouldFail, setServerShouldFail] = useState(false)\n\n\tconst table = useDataGrid<User>({\n\t\tdata,\n\t\tcolumns,\n\t\tcreating: {\n\t\t\tmode: 'modal',\n\t\t\tvalidate: { schema: userSchema },\n\t\t\tonSave: async ({ values }) => {\n\t\t\t\t// Simulate latency so the spinner is visible.\n\t\t\t\tawait new Promise<void>((r) => {\n\t\t\t\t\tsetTimeout(r, 400)\n\t\t\t\t})\n\t\t\t\tif (serverShouldFail) {\n\t\t\t\t\tthrow new ValidationError({\n\t\t\t\t\t\terrors: { email: ['email already in use'] },\n\t\t\t\t\t\tformError: 'Could not save — try a different email',\n\t\t\t\t\t})\n\t\t\t\t}\n\t\t\t\tsetData((prev) => [...prev, { id: Date.now(), active: true, ...values } as User])\n\t\t\t},\n\t\t},\n\t})\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '0.75rem', color: '#64748b', fontSize: '0.875rem' }}>\n\t\t\t\tOpen the create form via <strong>Add row</strong>. Validation runs on submit using a zod schema; the server\n\t\t\t\tsimulator can be toggled to throw <code>ValidationError</code>.\n\t\t\t</p>\n\t\t\t<label style={{ display: 'inline-flex', alignItems: 'center', gap: '0.5rem', marginBottom: '1rem' }}>\n\t\t\t\t<input\n\t\t\t\t\ttype='checkbox'\n\t\t\t\t\tchecked={serverShouldFail}\n\t\t\t\t\tonChange={(e) => {\n\t\t\t\t\t\tsetServerShouldFail(e.target.checked)\n\t\t\t\t\t}}\n\t\t\t\t/>\n\t\t\t\tSimulate server-side rejection\n\t\t\t</label>\n\t\t\t<DataGrid<User> table={table} />\n\t\t</div>\n\t)\n}\n",
  "editing-validation": "'use client'\n\nimport { ValidationError } from '@ez-kit/data-grid-react'\nimport { useState } from 'react'\nimport { z } from 'zod'\n\nimport { DataGrid, useDataGrid } from 'shared/DataGrid'\n\nimport { columns, INITIAL_DATA, type User } from '../_data'\n\nconst userSchema = z.object({\n\tname: z.string().min(2, 'must be at least 2 chars'),\n\temail: z.email('must be a valid email'),\n\tage: z.number().int().min(18, 'must be 18 or older').max(120, 'must be ≤120'),\n})\n\nconst TAKEN_EMAILS = new Set(['taken@example.com'])\n\nexport function EditingValidationExample() {\n\tconst [data, setData] = useState(INITIAL_DATA)\n\n\tconst table = useDataGrid<User>({\n\t\tdata,\n\t\tcolumns,\n\t\tediting: {\n\t\t\tmode: 'row',\n\t\t\tvalidate: { schema: userSchema },\n\t\t\tonSave: async ({ rowId, values }) => {\n\t\t\t\tawait new Promise<void>((r) => {\n\t\t\t\t\tsetTimeout(r, 350)\n\t\t\t\t})\n\t\t\t\tif (typeof values.email === 'string' && TAKEN_EMAILS.has(values.email)) {\n\t\t\t\t\tthrow new ValidationError({\n\t\t\t\t\t\terrors: { email: ['already in use'] },\n\t\t\t\t\t})\n\t\t\t\t}\n\t\t\t\tsetData((prev) => prev.map((row) => (String(row.id) === rowId ? { ...row, ...values } : row)))\n\t\t\t},\n\t\t},\n\t})\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#64748b', fontSize: '0.875rem' }}>\n\t\t\t\tClick <strong>Edit</strong> on any row, then <strong>Save</strong>. Try setting the email to{' '}\n\t\t\t\t<code>taken@example.com</code> to see the server simulator throw <code>ValidationError</code>.\n\t\t\t</p>\n\t\t\t<DataGrid<User> table={table} />\n\t\t</div>\n\t)\n}\n",
  "expanding-sub-content": "'use client'\n\nimport { defineColumns } from '@ez-kit/data-grid-react'\n\nimport { DataGrid, useDataGrid } from 'shared/DataGrid'\n\ntype Employee = {\n\tid: number\n\tname: string\n\trole: string\n\tdepartment: string\n\temail: string\n\tbio: string\n\tlocation: string\n\tstartDate: string\n}\n\nconst EMPLOYEES: Employee[] = [\n\t{\n\t\tid: 1,\n\t\tname: 'Alice Johnson',\n\t\trole: 'Senior Engineer',\n\t\tdepartment: 'Engineering',\n\t\temail: 'alice@example.com',\n\t\tbio: 'Full-stack engineer with 8 years of experience in React and Node.js.',\n\t\tlocation: 'San Francisco, CA',\n\t\tstartDate: '2018-03-12',\n\t},\n\t{\n\t\tid: 2,\n\t\tname: 'Bob Smith',\n\t\trole: 'Product Manager',\n\t\tdepartment: 'Product',\n\t\temail: 'bob@example.com',\n\t\tbio: 'Product leader focused on developer tools and platform products.',\n\t\tlocation: 'New York, NY',\n\t\tstartDate: '2020-07-01',\n\t},\n\t{\n\t\tid: 3,\n\t\tname: 'Carol White',\n\t\trole: 'Designer',\n\t\tdepartment: 'Design',\n\t\temail: 'carol@example.com',\n\t\tbio: 'UX designer specialising in data-dense interfaces and design systems.',\n\t\tlocation: 'Austin, TX',\n\t\tstartDate: '2021-01-15',\n\t},\n\t{\n\t\tid: 4,\n\t\tname: 'Dave Brown',\n\t\trole: 'Data Analyst',\n\t\tdepartment: 'Analytics',\n\t\temail: 'dave@example.com',\n\t\tbio: 'Transforms raw data into actionable insights using SQL and Python.',\n\t\tlocation: 'Seattle, WA',\n\t\tstartDate: '2019-11-05',\n\t},\n\t{\n\t\tid: 5,\n\t\tname: 'Eve Davis',\n\t\trole: 'DevOps Engineer',\n\t\tdepartment: 'Infrastructure',\n\t\temail: 'eve@example.com',\n\t\tbio: 'Kubernetes enthusiast maintaining cloud infrastructure at scale.',\n\t\tlocation: 'Chicago, IL',\n\t\tstartDate: '2022-04-20',\n\t},\n]\n\nconst columns = defineColumns<Employee>([\n\t{ accessorKey: 'name', header: 'Name' },\n\t{ accessorKey: 'role', header: 'Role' },\n\t{ accessorKey: 'department', header: 'Department' },\n])\n\nexport function ExpandingSubContentExample() {\n\tconst table = useDataGrid({\n\t\tdata: EMPLOYEES,\n\t\tcolumns,\n\t\texpanding: {\n\t\t\trenderExpanded: ({ row }) => {\n\t\t\t\tconst emp = row.original\n\t\t\t\treturn (\n\t\t\t\t\t<div className='gap-8 flex-wrap flex'>\n\t\t\t\t\t\t<div>\n\t\t\t\t\t\t\t<div className='mb-1 font-semibold'>Contact</div>\n\t\t\t\t\t\t\t<div>{emp.email}</div>\n\t\t\t\t\t\t\t<div>{emp.location}</div>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<div>\n\t\t\t\t\t\t\t<div className='mb-1 font-semibold'>Start Date</div>\n\t\t\t\t\t\t\t<div>{emp.startDate}</div>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<div className='flex-1'>\n\t\t\t\t\t\t\t<div className='mb-1 font-semibold'>Bio</div>\n\t\t\t\t\t\t\t<div className='text-muted-foreground'>{emp.bio}</div>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t</div>\n\t\t\t\t)\n\t\t\t},\n\t\t},\n\t})\n\n\treturn <DataGrid table={table} />\n}\n",
  "expanding-tree": "'use client'\n\nimport { defineColumns } from '@ez-kit/data-grid-react'\n\nimport { DataGrid, useDataGrid } from 'shared/DataGrid'\n\ntype OrgNode = {\n\tid: number\n\tname: string\n\trole: string\n\theadcount: number\n\tchildren?: OrgNode[]\n}\n\nconst ORG_DATA: OrgNode[] = [\n\t{\n\t\tid: 1,\n\t\tname: 'Engineering',\n\t\trole: 'Department',\n\t\theadcount: 24,\n\t\tchildren: [\n\t\t\t{\n\t\t\t\tid: 11,\n\t\t\t\tname: 'Frontend',\n\t\t\t\trole: 'Team',\n\t\t\t\theadcount: 8,\n\t\t\t\tchildren: [\n\t\t\t\t\t{ id: 111, name: 'Alice Johnson', role: 'Senior Engineer', headcount: 1 },\n\t\t\t\t\t{ id: 112, name: 'Tom Lee', role: 'Engineer', headcount: 1 },\n\t\t\t\t],\n\t\t\t},\n\t\t\t{\n\t\t\t\tid: 12,\n\t\t\t\tname: 'Backend',\n\t\t\t\trole: 'Team',\n\t\t\t\theadcount: 10,\n\t\t\t\tchildren: [\n\t\t\t\t\t{ id: 121, name: 'Carlos Mendez', role: 'Lead Engineer', headcount: 1 },\n\t\t\t\t\t{ id: 122, name: 'Sara Kim', role: 'Engineer', headcount: 1 },\n\t\t\t\t],\n\t\t\t},\n\t\t\t{\n\t\t\t\tid: 13,\n\t\t\t\tname: 'Infrastructure',\n\t\t\t\trole: 'Team',\n\t\t\t\theadcount: 6,\n\t\t\t\tchildren: [{ id: 131, name: 'Eve Davis', role: 'DevOps Engineer', headcount: 1 }],\n\t\t\t},\n\t\t],\n\t},\n\t{\n\t\tid: 2,\n\t\tname: 'Product',\n\t\trole: 'Department',\n\t\theadcount: 10,\n\t\tchildren: [\n\t\t\t{ id: 21, name: 'Bob Smith', role: 'Product Manager', headcount: 1 },\n\t\t\t{ id: 22, name: 'Mia Chen', role: 'Product Manager', headcount: 1 },\n\t\t],\n\t},\n\t{\n\t\tid: 3,\n\t\tname: 'Design',\n\t\trole: 'Department',\n\t\theadcount: 6,\n\t\tchildren: [\n\t\t\t{ id: 31, name: 'Carol White', role: 'Lead Designer', headcount: 1 },\n\t\t\t{ id: 32, name: 'Jake Moore', role: 'Designer', headcount: 1 },\n\t\t],\n\t},\n]\n\nconst columns = defineColumns<OrgNode>([\n\t{ accessorKey: 'name', header: 'Name' },\n\t{ accessorKey: 'role', header: 'Role' },\n\t{ accessorKey: 'headcount', header: 'Headcount', cell: { type: 'number' } },\n])\n\nexport function ExpandingTreeExample() {\n\tconst table = useDataGrid({\n\t\tdata: ORG_DATA,\n\t\tcolumns,\n\t\texpanding: {\n\t\t\tvariant: 'tree',\n\t\t},\n\t})\n\n\treturn <DataGrid table={table} />\n}\n",
  "expanding-controlled": "'use client'\n\nimport { defineColumns } from '@ez-kit/data-grid-react'\nimport { useState } from 'react'\n\nimport { DataGrid, useDataGrid } from 'shared/DataGrid'\n\nimport type { TableState } from '@ez-kit/data-grid-react'\n\ntype Employee = {\n\tid: number\n\tname: string\n\trole: string\n\tdepartment: string\n\tnotes: string\n}\n\nconst EMPLOYEES: Employee[] = [\n\t{\n\t\tid: 1,\n\t\tname: 'Alice Johnson',\n\t\trole: 'Senior Engineer',\n\t\tdepartment: 'Engineering',\n\t\tnotes: 'On-call rotation lead. Prefers async communication.',\n\t},\n\t{\n\t\tid: 2,\n\t\tname: 'Bob Smith',\n\t\trole: 'Product Manager',\n\t\tdepartment: 'Product',\n\t\tnotes: 'Owns the roadmap for Q3. Weekly sync every Tuesday.',\n\t},\n\t{\n\t\tid: 3,\n\t\tname: 'Carol White',\n\t\trole: 'Designer',\n\t\tdepartment: 'Design',\n\t\tnotes: 'Design system maintainer. Figma token updates in progress.',\n\t},\n\t{\n\t\tid: 4,\n\t\tname: 'Dave Brown',\n\t\trole: 'Data Analyst',\n\t\tdepartment: 'Analytics',\n\t\tnotes: 'Monthly reporting due on the 5th. Warehouse access required.',\n\t},\n]\n\nconst columns = defineColumns<Employee>([\n\t{ accessorKey: 'name', header: 'Name' },\n\t{ accessorKey: 'role', header: 'Role' },\n\t{ accessorKey: 'department', header: 'Department' },\n])\n\nexport function ExpandingControlledExample() {\n\tconst [tableState, setTableState] = useState<Partial<TableState>>({ expanded: {} })\n\tconst expanded = (tableState.expanded ?? {}) as Record<string, boolean>\n\tconst allIds = EMPLOYEES.map((_, i) => String(i))\n\tconst allExpanded = allIds.every((id) => expanded[id])\n\n\tconst table = useDataGrid({\n\t\tdata: EMPLOYEES,\n\t\tcolumns,\n\t\tstate: tableState,\n\t\tonStateChange: (updater) => {\n\t\t\tsetTableState((prev) => (typeof updater === 'function' ? updater(prev as TableState) : updater))\n\t\t},\n\t\texpanding: {\n\t\t\trenderExpanded: ({ row }) => (\n\t\t\t\t<div>\n\t\t\t\t\t<span style={{ fontWeight: 600 }}>Notes: </span>\n\t\t\t\t\t{row.original.notes}\n\t\t\t\t</div>\n\t\t\t),\n\t\t},\n\t})\n\n\treturn (\n\t\t<div>\n\t\t\t<div style={{ marginBottom: '0.75rem', display: 'flex', gap: '0.5rem' }}>\n\t\t\t\t<button\n\t\t\t\t\ttype='button'\n\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\tsetTableState((prev) => ({\n\t\t\t\t\t\t\t...prev,\n\t\t\t\t\t\t\texpanded: Object.fromEntries(allIds.map((id) => [id, true])),\n\t\t\t\t\t\t}))\n\t\t\t\t\t}}\n\t\t\t\t\tdisabled={allExpanded}\n\t\t\t\t>\n\t\t\t\t\tExpand all\n\t\t\t\t</button>\n\t\t\t\t<button\n\t\t\t\t\ttype='button'\n\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\tsetTableState((prev) => ({ ...prev, expanded: {} }))\n\t\t\t\t\t}}\n\t\t\t\t\tdisabled={Object.keys(expanded).length === 0}\n\t\t\t\t>\n\t\t\t\t\tCollapse all\n\t\t\t\t</button>\n\t\t\t</div>\n\t\t\t<DataGrid table={table} />\n\t\t</div>\n\t)\n}\n",
  "row-pinning-sticky-header": "'use client'\n\nimport { useState } from 'react'\n\nimport { DataGrid, useDataGrid } from 'shared/DataGrid'\n\nimport { columns, makeUsers } from '../_data'\n\nexport function RowPinningStickyHeaderExample() {\n\tconst [data] = useState(makeUsers(100))\n\n\tconst table = useDataGrid({\n\t\tdata,\n\t\tcolumns,\n\t\tpinning: { row: { top: true, bottom: true } },\n\t\tstickyHeader: true,\n\t})\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#666' }}>\n\t\t\t\tPinned rows stay locked to the top and bottom while the header sticks to the top of the\n\t\t\t\tscroll container. Container height is controlled by <code>--dg-table-max-height</code>{' '}\n\t\t\t\t(default 400px).\n\t\t\t</p>\n\t\t\t<DataGrid table={table} />\n\t\t</div>\n\t)\n}\n",
  "virtualized": "'use client'\n\nimport { useMemo } from 'react'\n\nimport { DataGrid, useDataGrid } from 'shared/DataGrid'\n\nimport { columns, type User } from './_data'\n\nconst VIRTUAL_ROW_COUNT = 10_000\n\nfunction makeVirtualData(): User[] {\n\treturn Array.from({ length: VIRTUAL_ROW_COUNT }, (_, i) => ({\n\t\tid: i + 1,\n\t\tname: `User ${String(i + 1)}`,\n\t\temail: `user${String(i + 1)}@example.com`,\n\t\tage: 20 + (i % 50),\n\t\tactive: i % 3 !== 0,\n\t}))\n}\n\nexport function VirtualizedExample() {\n\tconst data = useMemo(() => makeVirtualData(), [])\n\n\tconst table = useDataGrid({\n\t\tdata,\n\t\tcolumns,\n\t\tsorting: true,\n\t\tstickyHeader: true,\n\t\tvirtualized: { row: { estimateSize: 49, overscan: 10 } },\n\t})\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#666' }}>\n\t\t\t\tOnly visible rows are rendered. Scroll to see all {VIRTUAL_ROW_COUNT.toLocaleString()} rows. Container height is\n\t\t\t\tcontrolled by <code>--dg-virtual-height</code> (default 600px).\n\t\t\t</p>\n\t\t\t<DataGrid table={table} />\n\t\t</div>\n\t)\n}\n",
  "crud-server": "'use client'\n\nimport { useState } from 'react'\n\nimport { CrudClientExample } from './CrudClientExample'\n\nconst SUB_TABS = [\n\t{ id: 'client', label: 'Client Side', Component: CrudClientExample },\n\t{ id: 'server', label: 'Server Side', Component: ServerSidePlaceholder },\n] as const\n\ntype SubTabId = (typeof SUB_TABS)[number]['id']\n\nfunction ServerSidePlaceholder() {\n\treturn <p style={{ color: '#64748b', fontSize: '0.875rem' }}>Server-side CRUD example coming soon.</p>\n}\n\nexport function CrudExample() {\n\tconst [active, setActive] = useState<SubTabId>('client')\n\tconst tab = SUB_TABS.find((t) => t.id === active) ?? SUB_TABS[0]\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#64748b', fontSize: '0.875rem' }}>\n\t\t\t\tFull CRUD demo: create, edit, delete rows — plus sorting, filtering (popover), column visibility, column\n\t\t\t\tpinning, pagination, and bulk selection.\n\t\t\t</p>\n\n\t\t\t<div\n\t\t\t\tstyle={{\n\t\t\t\t\tdisplay: 'flex',\n\t\t\t\t\tgap: '0.25rem',\n\t\t\t\t\tborderBottom: '1px solid #e2e8f0',\n\t\t\t\t\tmarginBottom: '1.5rem',\n\t\t\t\t}}\n\t\t\t>\n\t\t\t\t{SUB_TABS.map((t) => (\n\t\t\t\t\t<button\n\t\t\t\t\t\tkey={t.id}\n\t\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\t\tsetActive(t.id)\n\t\t\t\t\t\t}}\n\t\t\t\t\t\tstyle={{\n\t\t\t\t\t\t\tpadding: '0.375rem 0.75rem',\n\t\t\t\t\t\t\tborder: 'none',\n\t\t\t\t\t\t\tborderBottom: active === t.id ? '2px solid #0f172a' : '2px solid transparent',\n\t\t\t\t\t\t\tbackground: 'none',\n\t\t\t\t\t\t\tcursor: 'pointer',\n\t\t\t\t\t\t\tfontSize: '0.875rem',\n\t\t\t\t\t\t\tfontWeight: active === t.id ? 600 : 400,\n\t\t\t\t\t\t\tcolor: active === t.id ? '#0f172a' : '#64748b',\n\t\t\t\t\t\t\tmarginBottom: '-1px',\n\t\t\t\t\t\t}}\n\t\t\t\t\t>\n\t\t\t\t\t\t{t.label}\n\t\t\t\t\t</button>\n\t\t\t\t))}\n\t\t\t</div>\n\n\t\t\t<tab.Component />\n\t\t</div>\n\t)\n}\n",
  "crud-client": "'use client'\n\nimport { DataGrid, useDataGrid } from 'shared/DataGrid'\n\nimport { crudColumns } from './columns'\nimport { type Employee, useEmployeeStore } from './use-employee-store'\n\nexport function CrudClientExample() {\n\tconst { data, add, update, remove, removeMany } = useEmployeeStore()\n\n\tconst table = useDataGrid({\n\t\tdata,\n\t\tcolumns: crudColumns,\n\t\tgetRowId: (row) => String(row.id),\n\t\tsorting: true,\n\t\tfiltering: { variant: 'popover' },\n\t\tpagination: { pageSize: 10 },\n\t\tpageSizer: { items: [5, 10, 20, 50] },\n\t\tcolumnVisibility: { toolbar: true },\n\t\tpinning: { column: true },\n\t\tselection: true,\n\t\tcreating: {\n\t\t\tmode: 'row',\n\t\t\tonSave: ({ values }) => {\n\t\t\t\tadd(values)\n\t\t\t},\n\t\t},\n\t\tediting: {\n\t\t\tmode: 'row',\n\t\t\tonSave: ({ rowId, values }) => {\n\t\t\t\tupdate(Number(rowId), values)\n\t\t\t},\n\t\t},\n\t\tdeleting: {\n\t\t\tonDelete: ({ row }) => {\n\t\t\t\tremove(row.original.id)\n\t\t\t},\n\t\t\tconfirmation: {\n\t\t\t\ttitle: 'Delete employee?',\n\t\t\t\tdescription: (row) =>\n\t\t\t\t\t`Are you sure you want to delete \"${(row.original as Employee).name}\"? This action cannot be undone.`,\n\t\t\t},\n\t\t},\n\t\tselectionBar: {\n\t\t\tonDelete: ({ selectedRows, clearSelection }) => {\n\t\t\t\tremoveMany(selectedRows.map((r) => r.original.id))\n\t\t\t\tclearSelection()\n\t\t\t},\n\t\t},\n\t})\n\n\treturn <DataGrid table={table} />\n}\n",
  "controlled-state": "'use client'\n\nimport { useState } from 'react'\n\nimport { DataGrid, useDataGrid } from 'shared/DataGrid'\n\nimport { columns, INITIAL_DATA } from './_data'\n\nimport type { TableState } from '@ez-kit/data-grid-react'\n\ntype ControlledState = Pick<TableState, 'sorting' | 'pagination'>\n\nexport function ControlledStateExample() {\n\tconst [tableState, setTableState] = useState<Partial<ControlledState>>({\n\t\tsorting: [{ id: 'name', desc: false }],\n\t\tpagination: { pageIndex: 0, pageSize: 3 },\n\t})\n\n\tconst table = useDataGrid({\n\t\tdata: INITIAL_DATA,\n\t\tcolumns,\n\t\tsorting: true,\n\t\tpagination: true,\n\t\tstate: tableState,\n\t\tonStateChange: (updater) => {\n\t\t\tsetTableState((prev) =>\n\t\t\t\ttypeof updater === 'function' ? updater(prev as TableState) : updater,\n\t\t\t)\n\t\t},\n\t})\n\n\tconst resetSort = (): void => {\n\t\tsetTableState((prev) => ({ ...prev, sorting: [] }))\n\t}\n\n\tconst firstSort = tableState.sorting?.[0]\n\tconst sortLabel = firstSort ? `${firstSort.id} ${firstSort.desc ? '↓' : '↑'}` : 'none'\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#666' }}>\n\t\t\t\tSorting and pagination state are fully controlled by React state. Click a column header to\n\t\t\t\tsort — state is owned by the parent and can be reset or preset programmatically.\n\t\t\t</p>\n\t\t\t<div style={{ display: 'flex', alignItems: 'center', gap: '1rem', marginBottom: '1rem' }}>\n\t\t\t\t<span style={{ fontSize: '0.875rem', color: '#666' }}>\n\t\t\t\t\tActive sort: <strong>{sortLabel}</strong>\n\t\t\t\t</span>\n\t\t\t\t<button\n\t\t\t\t\tonClick={resetSort}\n\t\t\t\t\tstyle={{\n\t\t\t\t\t\tpadding: '0.25rem 0.75rem',\n\t\t\t\t\t\tfontSize: '0.875rem',\n\t\t\t\t\t\tborder: '1px solid #d1d5db',\n\t\t\t\t\t\tborderRadius: '0.375rem',\n\t\t\t\t\t\tbackground: 'white',\n\t\t\t\t\t\tcursor: 'pointer',\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\tReset sort\n\t\t\t\t</button>\n\t\t\t</div>\n\t\t\t<DataGrid table={table} />\n\t\t</div>\n\t)\n}\n",
  "fallbacks": "'use client'\n\nimport { useState } from 'react'\n\nimport { DataGrid, useDataGrid } from 'shared/DataGrid'\n\nimport { columns, INITIAL_DATA } from './_data'\n\nconst EMPTY_DATA: typeof INITIAL_DATA = []\n\ntype Mode = 'loading' | 'empty' | 'no-results' | 'normal'\n\nconst MODE_LABELS: Record<Mode, string> = {\n\tloading: 'Loading',\n\tempty: 'Empty data',\n\t'no-results': 'No results',\n\tnormal: 'Normal',\n}\n\nfunction TabButton({ active, onClick, children }: { active: boolean; onClick: () => void; children: string }) {\n\treturn (\n\t\t<button\n\t\t\ttype='button'\n\t\t\tonClick={onClick}\n\t\t\tstyle={{\n\t\t\t\tpadding: '0.375rem 0.875rem',\n\t\t\t\tfontSize: 13,\n\t\t\t\tfontWeight: active ? 600 : 400,\n\t\t\t\tborderRadius: 6,\n\t\t\t\tborder: active ? '1px solid #6366f1' : '1px solid #e2e8f0',\n\t\t\t\tbackground: active ? '#6366f1' : 'white',\n\t\t\t\tcolor: active ? 'white' : '#475569',\n\t\t\t\tcursor: 'pointer',\n\t\t\t\ttransition: 'all 120ms',\n\t\t\t}}\n\t\t>\n\t\t\t{children}\n\t\t</button>\n\t)\n}\n\nexport function FallbacksExample() {\n\tconst [mode, setMode] = useState<Mode>('loading')\n\n\tconst table = useDataGrid({\n\t\tdata: mode === 'empty' ? EMPTY_DATA : INITIAL_DATA,\n\t\tcolumns,\n\t\tsorting: true,\n\t\tfiltering: true,\n\t\tpagination: { pageSize: 5 },\n\t\tstate: {\n\t\t\tloading: { isPending: mode === 'loading', isFetching: false, isError: false, error: null },\n\t\t\t// Reset column filters when leaving 'no-results' mode\n\t\t\t...(mode !== 'no-results' ? { columnFilters: [] } : {}),\n\t\t},\n\t})\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#666', fontSize: 14 }}>\n\t\t\t\tFallback states render automatically when the grid has no visible rows. Switch between states to preview\n\t\t\t\teach one.\n\t\t\t</p>\n\n\t\t\t<div style={{ display: 'flex', gap: '0.5rem', marginBottom: '1.5rem', flexWrap: 'wrap' }}>\n\t\t\t\t{(Object.keys(MODE_LABELS) as Mode[]).map((m) => (\n\t\t\t\t\t<TabButton\n\t\t\t\t\t\tkey={m}\n\t\t\t\t\t\tactive={mode === m}\n\t\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\t\tsetMode(m)\n\t\t\t\t\t\t}}\n\t\t\t\t\t>\n\t\t\t\t\t\t{MODE_LABELS[m]}\n\t\t\t\t\t</TabButton>\n\t\t\t\t))}\n\t\t\t</div>\n\n\t\t\t{mode === 'no-results' && (\n\t\t\t\t<p style={{ marginBottom: '0.75rem', fontSize: 13, color: '#64748b' }}>\n\t\t\t\t\tType something that matches no rows in the filter inputs below column headers.\n\t\t\t\t</p>\n\t\t\t)}\n\n\t\t\t<DataGrid table={table} />\n\t\t</div>\n\t)\n}\n",
  "infinite-scroll-auto": "'use client'\n\nimport { DataGrid, useDataGrid } from 'shared/DataGrid'\n\nimport { columns } from '../_data'\n\nimport { usePagedUsers } from './_use-paged-users'\n\n/**\n * Auto infinite scroll. The grid detects the bottom edge and calls `onLoadMore`;\n * the consumer owns the data (fetch + append into React state) and declares\n * `hasNextPage` from the API response. Page 1 loads on mount.\n */\nexport function InfiniteScrollAutoExample() {\n\tconst { data, state, hasNextPage, onLoadMore } = usePagedUsers()\n\n\tconst table = useDataGrid({\n\t\tdata,\n\t\tcolumns,\n\t\tstate,\n\t\tstickyHeader: true,\n\t\tpagination: { mode: 'infinite', hasNextPage, onLoadMore },\n\t})\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#64748b', fontSize: '0.875rem' }}>\n\t\t\t\tScroll to the bottom — the next page loads automatically until the data is exhausted.\n\t\t\t</p>\n\t\t\t<DataGrid table={table} />\n\t\t</div>\n\t)\n}\n",
  "infinite-scroll-manual": "'use client'\n\nimport { DataGrid, useDataGrid } from 'shared/DataGrid'\n\nimport { columns } from '../_data'\n\nimport { usePagedUsers } from './_use-paged-users'\n\n/**\n * Manual infinite scroll. Auto detection is off; a \"Load more\" button (the injected\n * `LoadMoreRow`) drives the same `onLoadMore`. Page 1 still loads on mount; only\n * subsequent pages require the button.\n */\nexport function InfiniteScrollManualExample() {\n\tconst { data, state, hasNextPage, onLoadMore } = usePagedUsers()\n\n\tconst table = useDataGrid({\n\t\tdata,\n\t\tcolumns,\n\t\tstate,\n\t\tstickyHeader: true,\n\t\tpagination: { mode: 'infinite', trigger: 'manual', hasNextPage, onLoadMore },\n\t})\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#64748b', fontSize: '0.875rem' }}>\n\t\t\t\tClick <strong>Load more</strong> to fetch the next page — nothing loads on scroll alone.\n\t\t\t</p>\n\t\t\t<DataGrid table={table} />\n\t\t</div>\n\t)\n}\n",
  "infinite-scroll-virtualized": "'use client'\n\nimport { DataGrid, useDataGrid } from 'shared/DataGrid'\n\nimport { columns } from '../_data'\n\nimport { usePagedUsers } from './_use-paged-users'\n\n/**\n * Infinite scroll combined with row virtualization. Detection switches to the\n * virtualizer's last rendered index, so only visible rows render while pages\n * keep loading on scroll. Page 1 loads on mount.\n */\nexport function InfiniteScrollVirtualizedExample() {\n\tconst { data, state, hasNextPage, onLoadMore } = usePagedUsers()\n\n\tconst table = useDataGrid({\n\t\tdata,\n\t\tcolumns,\n\t\tstate,\n\t\tstickyHeader: true,\n\t\tvirtualized: { row: { estimateSize: 49, overscan: 10 } },\n\t\tpagination: { mode: 'infinite', hasNextPage, onLoadMore, threshold: { rows: 8 } },\n\t})\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#64748b', fontSize: '0.875rem' }}>\n\t\t\t\tVirtualized + infinite: rows render on demand and pages load as you approach the end.\n\t\t\t</p>\n\t\t\t<DataGrid table={table} />\n\t\t</div>\n\t)\n}\n",
  "infinite-scroll-reset": "'use client'\n\nimport { DataGrid, useDataGrid } from 'shared/DataGrid'\n\nimport { columns } from '../_data'\n\nimport { usePagedUsers } from './_use-paged-users'\n\n/**\n * Reset on query change. With server-side (`manual`) sorting, the accumulated rows\n * belong to the previous query, so on sort change the consumer drops them and\n * refetches page 1 with the new sort (`reset`). The grid handles its own side\n * (clears error, re-arms detection, scrolls to top).\n */\nexport function InfiniteScrollResetExample() {\n\tconst { data, state, hasNextPage, onLoadMore, reset } = usePagedUsers()\n\n\tconst table = useDataGrid({\n\t\tdata,\n\t\tcolumns,\n\t\tstate,\n\t\tstickyHeader: true,\n\t\tsorting: {\n\t\t\tmanual: true,\n\t\t\tonChange: (sorting) => {\n\t\t\t\tconst first = sorting[0]\n\t\t\t\tvoid reset(first ? { id: first.id, desc: first.desc } : undefined)\n\t\t\t},\n\t\t},\n\t\tpagination: { mode: 'infinite', hasNextPage, onLoadMore },\n\t})\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#64748b', fontSize: '0.875rem' }}>\n\t\t\t\tChange the sort by clicking a column header — accumulated rows are dropped and page 1 is refetched for the new\n\t\t\t\torder.\n\t\t\t</p>\n\t\t\t<DataGrid table={table} />\n\t\t</div>\n\t)\n}\n",
  "server-data": "'use client'\n\nimport { useCallback, useEffect, useRef, useState } from 'react'\n\nimport { DataGrid, useDataGrid } from 'shared/DataGrid'\n\nimport { makeUsers, columns, type User } from './_data'\n\nimport type { ColumnFiltersState, SortingState } from '@ez-kit/data-grid-react'\n\n// ---------------------------------------------------------------------------\n// Simulated server dataset + mock fetch\n// ---------------------------------------------------------------------------\n\nconst ALL_USERS: User[] = makeUsers(120)\n\nconst PAGE_SIZE = 10\nconst NETWORK_DELAY_MS = 700\n\ntype ServerQuery = {\n\tpageIndex: number\n\tpageSize: number\n\tsorting: SortingState\n\tcolumnFilters: ColumnFiltersState\n\tglobalFilter: string\n}\n\ntype ServerPage = {\n\trows: User[]\n\trowCount: number\n}\n\nfunction applySort(rows: User[], sorting: SortingState): User[] {\n\tif (sorting.length === 0) return rows\n\treturn [...rows].sort((a, b) => {\n\t\tfor (const s of sorting) {\n\t\t\tconst av = a[s.id as keyof User]\n\t\t\tconst bv = b[s.id as keyof User]\n\t\t\tif (av < bv) return s.desc ? 1 : -1\n\t\t\tif (av > bv) return s.desc ? -1 : 1\n\t\t}\n\t\treturn 0\n\t})\n}\n\nfunction applyFilters(rows: User[], columnFilters: ColumnFiltersState, globalFilter: string): User[] {\n\tlet result = rows\n\n\tfor (const f of columnFilters) {\n\t\tconst val = String(f.value).toLowerCase()\n\t\tresult = result.filter((row) => String(row[f.id as keyof User]).toLowerCase().includes(val))\n\t}\n\n\tif (globalFilter.trim()) {\n\t\tconst q = globalFilter.trim().toLowerCase()\n\t\tresult = result.filter((row) =>\n\t\t\tObject.values(row).some((v) => String(v).toLowerCase().includes(q)),\n\t\t)\n\t}\n\n\treturn result\n}\n\nfunction fetchPage(query: ServerQuery): Promise<ServerPage> {\n\treturn new Promise((resolve) => {\n\t\tsetTimeout(() => {\n\t\t\tconst filtered = applyFilters(ALL_USERS, query.columnFilters, query.globalFilter)\n\t\t\tconst sorted = applySort(filtered, query.sorting)\n\t\t\tconst start = query.pageIndex * query.pageSize\n\t\t\tconst rows = sorted.slice(start, start + query.pageSize)\n\t\t\tresolve({ rows, rowCount: filtered.length })\n\t\t}, NETWORK_DELAY_MS)\n\t})\n}\n\n// ---------------------------------------------------------------------------\n// Example component\n// ---------------------------------------------------------------------------\n\nexport function ServerDataExample() {\n\tconst [rows, setRows] = useState<User[]>([])\n\tconst [rowCount, setRowCount] = useState(0)\n\tconst [pageIndex, setPageIndex] = useState(0)\n\tconst [pageSize, setPageSize] = useState(PAGE_SIZE)\n\tconst [sorting, setSorting] = useState<SortingState>([])\n\tconst [columnFilters, setColumnFilters] = useState<ColumnFiltersState>([])\n\tconst [globalFilter, setGlobalFilter] = useState('')\n\n\t// Controlled loading state — fed directly into state.loading.\n\tconst [isPending, setIsPending] = useState(true)\n\tconst [isFetching, setIsFetching] = useState(false)\n\tconst [isError, setIsError] = useState(false)\n\tconst [error, setError] = useState<unknown>(null)\n\n\t// Keep a stable ref to the current query so the fetch fn always closes over\n\t// the latest values without needing them in the dependency array.\n\tconst queryRef = useRef<ServerQuery>({ pageIndex, pageSize, sorting, columnFilters, globalFilter })\n\tqueryRef.current = { pageIndex, pageSize, sorting, columnFilters, globalFilter }\n\n\t// Last-write-wins guard: increment a counter for each fetch; only the\n\t// response matching the latest counter is applied.\n\tconst fetchCountRef = useRef(0)\n\n\tconst table = useDataGrid({\n\t\tdata: rows,\n\t\tcolumns,\n\t\tpagination: {\n\t\t\tmanual: true,\n\t\t\trowCount,\n\t\t\tonChange: ({ pageIndex: pi, pageSize: ps }) => {\n\t\t\t\tsetPageIndex(pi)\n\t\t\t\tsetPageSize(ps)\n\t\t\t},\n\t\t},\n\t\tsorting: {\n\t\t\tmanual: true,\n\t\t\tonChange: (next) => {\n\t\t\t\tsetSorting(next)\n\t\t\t\tsetPageIndex(0)\n\t\t\t},\n\t\t},\n\t\tfiltering: {\n\t\t\tmanual: true,\n\t\t\tonChange: (next) => {\n\t\t\t\tsetColumnFilters(next)\n\t\t\t\tsetPageIndex(0)\n\t\t\t},\n\t\t},\n\t\t// Global filtering is made server-side by `filtering.manual` above —\n\t\t// TanStack's manual filtering covers the global filter too, so there is\n\t\t// no separate `globalFiltering.manual` flag.\n\t\tglobalFiltering: {\n\t\t\tonChange: (next) => {\n\t\t\t\tsetGlobalFilter(String(next ?? ''))\n\t\t\t\tsetPageIndex(0)\n\t\t\t},\n\t\t},\n\t\tstate: {\n\t\t\tpagination: { pageIndex, pageSize },\n\t\t\tsorting,\n\t\t\tcolumnFilters,\n\t\t\tglobalFilter,\n\t\t\tloading: { isPending, isFetching, isError, error },\n\t\t},\n\t})\n\n\tconst fetch = useCallback(async () => {\n\t\tconst id = ++fetchCountRef.current\n\n\t\t// On the very first load rows are empty → isPending drives the skeleton.\n\t\t// Subsequent fetches keep existing rows visible under the refetch overlay.\n\t\tif (rows.length === 0) {\n\t\t\tsetIsPending(true)\n\t\t}\n\t\tsetIsFetching(true)\n\t\tsetIsError(false)\n\t\tsetError(null)\n\n\t\ttry {\n\t\t\tconst page = await fetchPage(queryRef.current)\n\n\t\t\t// Drop stale responses (last-write-wins race protection).\n\t\t\tif (id !== fetchCountRef.current) return\n\n\t\t\tsetRows(page.rows)\n\t\t\tsetRowCount(page.rowCount)\n\t\t\tsetIsPending(false)\n\t\t\tsetIsFetching(false)\n\t\t} catch (err: unknown) {\n\t\t\tif (id !== fetchCountRef.current) return\n\n\t\t\tsetIsPending(false)\n\t\t\tsetIsFetching(false)\n\t\t\tsetIsError(true)\n\t\t\tsetError(err)\n\t\t}\n\t\t// eslint-disable-next-line react-hooks/exhaustive-deps\n\t}, [])\n\n\t// Load on mount and whenever any query param changes. This manual\n\t// fetch-in-effect is exactly what React Query removes — the `set-state-in-effect`\n\t// disable below is the smell that the recommended RQ pattern (see docs) avoids.\n\tuseEffect(() => {\n\t\t// eslint-disable-next-line react-hooks/set-state-in-effect\n\t\tvoid fetch()\n\t\t// eslint-disable-next-line react-hooks/exhaustive-deps\n\t}, [pageIndex, pageSize, sorting, columnFilters, globalFilter])\n\n\treturn (\n\t\t<div>\n\t\t\t<p style={{ marginBottom: '1rem', color: '#64748b', fontSize: '0.875rem' }}>\n\t\t\t\tAll data operations (sort, filter, global search, pagination) are delegated to the server.\n\t\t\t\tChange a filter or sort column to trigger a simulated network request — the refetch overlay\n\t\t\t\tappears automatically while data is loading. Rapid changes are coalesced via last-write-wins\n\t\t\t\trace protection.\n\t\t\t</p>\n\t\t\t<DataGrid table={table} />\n\t\t</div>\n\t)\n}\n",
  "state-persistence": "'use client'\n\nimport { defineColumns, extractState, parseState, useExtractedState } from '@ez-kit/data-grid-react'\nimport { useState } from 'react'\n\nimport { DataGrid, useDataGrid } from 'shared/DataGrid'\n\ntype Person = { id: number; name: string; role: string }\n\nconst PEOPLE: Person[] = [\n\t{ id: 1, name: 'Alice', role: 'Engineer' },\n\t{ id: 2, name: 'Bob', role: 'Designer' },\n\t{ id: 3, name: 'Carol', role: 'PM' },\n]\n\nconst columns = defineColumns<Person>([\n\t{ accessorKey: 'name', header: 'Name' },\n\t{ accessorKey: 'role', header: 'Role' },\n])\n\n// A previously-saved value (in a real app this comes from localStorage/URL).\nconst SAVED = { sorting: [{ id: 'name', desc: false }] }\n\nexport function StatePersistenceExample() {\n\tconst [initialState] = useState(() => parseState(SAVED))\n\tconst table = useDataGrid({ data: PEOPLE, columns, sorting: true, filtering: true, initialState })\n\tconst persisted = useExtractedState(table, { keys: ['sorting', 'columnFilters', 'pagination'] })\n\n\treturn (\n\t\t<div>\n\t\t\t<DataGrid table={table} />\n\t\t\t<pre>{JSON.stringify(persisted, null, 2)}</pre>\n\t\t\t<p>Snapshot for storage: {JSON.stringify(extractState(table.table))}</p>\n\t\t</div>\n\t)\n}\n"
} as const

export type DataGridSourceExampleId = keyof typeof dataGridExampleSources
